import { RESOURCES, BUILDINGS, INFRA, RESEARCH, STOCKS, BANKS, BONDS, VENTURES, TIERS, ACHIEVEMENTS, POLICIES, DAY, HOUR, PROPERTIES, RELEASE, PROGRAMMES, PROGRAMME_CHOICES } from './data.mjs';
import { price, quote, assets, capacity, warehouseCapacity, researchRate, buildingRate, buildQuote, upgradeQuote, bankRate, creditLimit, debtRate, researchCost, prestigeReward, referencePrice, optionQuote, supplyPlan, currentSupplyPlan, historySnapshot, legacyProgress } from './engine.mjs';
import { icon, mark } from './icons.mjs';
import * as C from './corporate.mjs';
import {optionPrice} from './math.mjs';
import {programmeOffer} from './campaign.mjs';
import {normalizeUI} from './ui-state.mjs';
import {chainBlueprint} from './chains.mjs';

export const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
export function number(n, decimals = 0) { return Number(n || 0).toLocaleString('de-DE', { maximumFractionDigits: decimals, minimumFractionDigits: decimals }); }
export function compact(n) {
  if(!Number.isFinite(n))return n===Infinity?'∞':n===-Infinity?'−∞':'—';
  if(Math.abs(n)>=1e15){const [coefficient,exponent]=n.toExponential(2).split('e');return `${number(Number(coefficient),2)} × 10^${Number(exponent)}`;}
  return Math.abs(n)>=1e12?`${number(n/1e12,2)} Bio.`:Math.abs(n) >= 1e9 ? `${number(n / 1e9, 2)} Mrd.` : Math.abs(n) >= 1e6 ? `${number(n / 1e6, 2)} Mio.` : Math.abs(n) >= 1e5 ? `${number(n / 1000, 1)} Tsd.` : number(n);
}
export const money = (n, decimals = 0) => `${number(n, decimals)} €`;
export const cash = n => `${compact(n)} €`;
export const signed = (n, suffix = ' €') => `${n >= 0 ? '+' : '−'}${compact(Math.abs(n))}${suffix}`;
export const pct = (n, decimals = 1) => `${number(n * 100, decimals)} %`;
export function duration(seconds) {
  const s = Math.max(0, Math.round(seconds));
  return s >= 86400 ? `${Math.floor(s / 86400)} T ${Math.floor(s % 86400 / 3600)} Std.` : s >= 3600 ? `${Math.floor(s / 3600)} Std. ${Math.floor(s % 3600 / 60)} Min.` : s >= 60 ? `${Math.floor(s / 60)} Min.` : `${s} Sek.`;
}
export const gameTime = s => `Tag ${Math.floor(s.elapsed / DAY) + 1} · ${String(Math.floor(s.elapsed % DAY / HOUR)).padStart(2, '0')}:${String(Math.floor(s.elapsed % HOUR / HOUR * 60)).padStart(2,'0')}`;
export const updateBanner = ui => ui.updateReady ? `<aside class="update-banner" aria-label="App-Update"><div>${icon('refresh')}<span><strong>Eine neue Version ist bereit.</strong><small>Dein Spielstand wird beim Wechsel gesichert.</small></span></div><button class="primary small" data-action="update">Update laden</button></aside>` : '';
const disabled = condition => condition ? ' disabled' : '';
const act = (action, id = '') => `data-action="${action}"${id !== '' ? ` data-id="${esc(id)}"` : ''}`;
const infoNames={building:BUILDINGS,infra:INFRA,resource:RESOURCES,research:RESEARCH,stock:STOCKS,bank:BANKS,bond:BONDS,venture:VENTURES,property:PROPERTIES,policy:POLICIES};
export const info = (key,label='') => `<button class="info-button" ${act('info',key)} aria-label="${esc(label||'Info: '+(infoNames[key.split(':')[0]]?.[key.split(':')[1]]?.name||'Funktionsweise'))}">${icon('info')}</button>`;
const empty = (name, text, glyph = 'box') => `<div class="empty">${icon(glyph)}<h3>${name}</h3><p>${text}</p></div>`;
const pageHelp={'Wertschöpfung':'planner','Angebot & Nachfrage':'resource:wood','Zeit ist Kapital':'credit','Wissen verändert alles':'research:forestry','Vertrauen wird belohnt':'contracts','Deine Geschichte':'offline','Was bleibt und weiterwächst':'programmes','Vermächtnis':'legacy','Analyse':'analysis'};
const head = (eyebrow, title, subtitle = '', extra = '') => `<div class="between page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title} ${info(pageHelp[eyebrow]||'overview','Diesen Bereich erklären')}</h1>${subtitle ? `<p>${subtitle}</p>` : ''}</div>${extra}</div>`;
const quantity = ui => `<div class="quantity-label">Menge ${info('quantity')}<div class="segmented quantity-controls" aria-label="Schrittweite"><button ${act('qtyScale',.1)} aria-label="Schrittweite durch zehn"${disabled(ui.qty===1)}>÷10</button><output class="number" aria-live="polite">${number(ui.qty)}</output><button ${act('qtyScale',10)} aria-label="Schrittweite mal zehn"${disabled(ui.qty===10000)}>×10</button><button ${act('qty',1)} class="ghost"${disabled(ui.qty===1)}>1</button></div></div>`;
const repeat = 'data-repeat="true"';
const preciseCash = n => Math.abs(n)<1e6?money(n,2):cash(n);

const resource = (id, n) => `<span class="resource">${icon(RESOURCES[id].icon)}${number(n, n % 1 ? 1 : 0)} ${RESOURCES[id].name}</span>`;
const meter = (name, used, total, suffix = '', warning = false) => `<div class="meter ${warning ? 'warning' : ''}"><div class="meter-label"><span>${name}</span><span class="number">${number(used, used % 1 ? 1 : 0)} / ${number(total)}${suffix}</span></div><div class="meter-track"><div class="meter-fill" style="width:${Math.min(100, used / Math.max(1,total) * 100)}%"></div></div></div>`;

export function chart(values, large = false, label = '') {
  const data = values.length > 1 ? values : [values[0] || 0, values[0] || 0];
  const min = Math.min(...data), max = Math.max(...data), span = max - min || Math.max(1, max * 0.05), w = large ? 600 : 100, h = large ? 150 : 32, padding = large ? 10 : 3;
  const points = data.map((v, i) => `${(i / (data.length - 1) * w).toFixed(1)},${(h - padding - ((v - min) / span) * (h - padding * 2)).toFixed(1)}`).join(' ');
  return `<svg class="${large ? 'chart' : 'spark'}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="${esc(label || 'Kursverlauf')}">${large ? `<line x1="0" x2="${w}" y1="${h/2}" y2="${h/2}"/><line x1="0" x2="${w}" y1="${h}" y2="${h}"/>` : ''}<polyline points="${points}"/></svg>`;
}

export function menu(s, ui) {
  return `<main class="menu-screen" id="content"><div class="menu-top">${mark()}<span class="status-pill"><i class="status-dot"></i>${ui.offlineReady ? 'Offline bereit' : 'Lokal. Privat. Zeitlos.'}</span></div>${updateBanner(ui)}<div class="menu-main"><div class="menu-hero"><div class="eyebrow">Eine Ökonomie · Ein Anfang</div><h1 class="menu-logo">NULL</h1><p class="menu-tagline">Aus wenig wird alles.</p><p class="menu-description">Ein paar Rohstoffe. Eine Entscheidung.<br>Ein System, das weiterdenkt.<br>Deine Wirtschaft wächst — auch ohne dich.</p></div><div class="menu-actions">${s ? `<button class="primary" ${act('continue')}><span>Unternehmen fortsetzen</span>${icon('arrow')}</button>` : ''}<button ${act('new')} class="${s ? '' : 'primary'}"><span>Neues Unternehmen</span>${icon('plus')}</button><button ${act('saves')}><span>Spielstände</span>${icon('save')}</button><button ${act('guide')}><span>Spielanleitung</span>${icon('book')}</button><button ${act('install')} class="ghost"><span>Auf dem iPhone installieren</span>${icon('download')}</button>${s ? `<div class="menu-save">${esc(s.name)} · ${TIERS[s.tier].name}<br>${gameTime(s)} · ${preciseCash(s.cash)} verfügbar</div>` : ''}</div></div><footer class="menu-footer"><span>PRODUKTION · HANDEL · KAPITAL</span><span>Kein Konto. Kein Tracking. Dein Spiel.</span></footer></main>`;
}

export function frame(s, ui, content) {
  const tabs = [['overview','dashboard','Übersicht'],['production','factory','Produktion'],['market','market','Markt'], ...(s.tier >= 1 ? [['finance','bank','Finanzen']] : []),['companies','building','Unternehmen']];
  const mobile = [...tabs,['more','more','Mehr']];
  const isMore = !mobile.some(([id]) => id === ui.tab);
  return `<div class="shell"><header class="topbar"><div class="row"><button class="brand" ${act('menu')} aria-label="Hauptmenü">${mark()}NULL</button><span class="company">${esc(s.name)}</span></div><div class="top-actions"><span class="status-pill"><i class="status-dot"></i>${ui.offlineReady ? 'Offline bereit' : 'Offline-Cache lädt'}</span><span class="clock mono">${gameTime(s)}</span><button class="speed-button ${ui.speed===100?'speed-active':''}" data-action="speed" aria-label="Simulation 100-fach beschleunigen während des Haltens" aria-pressed="${ui.speed===100}" title="Zum Beschleunigen gedrückt halten">100×<small>halten</small></button><button class="icon-button ghost" ${act('saves')} aria-label="Spielstände">${icon('save')}</button></div></header>${updateBanner(ui)}${companySwitch(s,ui)}<nav class="desktop-nav" aria-label="Spielbereiche">${tabs.map(([id,glyph,name]) => `<button ${act('tab',id)} class="${ui.tab === id ? 'active' : ''}">${icon(glyph)}${name}</button>`).join('')}<button ${act('tab','more')} class="${ui.tab === 'more' ? 'active' : ''}">${icon('more')}Mehr</button></nav><main id="content" data-key="view:${ui.tab}:${ui.companyId}:${ui.productionTab}:${ui.financeTab}" tabindex="-1">${content}</main><footer class="footer-note"><span>${ui.lastSaved ? `Automatisch gespeichert · ${new Date(ui.lastSaved).toLocaleTimeString('de-DE', {hour:'2-digit',minute:'2-digit'})}` : 'Automatische Sicherung alle 15 Sekunden'}${ui.saveError ? ' · Speicherung eingeschränkt' : ''}</span><span>${RELEASE} · 1 Spieltag = 24 echte Min.</span></footer><nav class="bottom-nav" aria-label="Spielbereiche" style="grid-template-columns:repeat(${mobile.length},1fr)">${mobile.map(([id,glyph,name]) => `<button ${act('tab',id)} class="${ui.tab === id || (id === 'more' && isMore) ? 'active' : ''}">${icon(glyph)}<span>${name}</span></button>`).join('')}</nav></div>`;
}

function tutorial(s) {
  if (!s.tutorial) return '';
  const steps = [
    { done:s.stats.built > 0, text:'Baue deinen ersten Holzfäller.', tab:'production' },
    { done:Object.values(s.automation).some(a => a.mode === 'sell' || a.mode === 'both'), text:'Verkaufe Überschüsse automatisch am Markt.', tab:'market' },
    { done:s.stats.contracts > 0, text:'Erfülle einen Lieferauftrag für eine Prämie.', tab:'contracts' },
    { done:s.tier >= 1, text:'Erreiche 2.000 € Vermögen. Entdecke mehr.', tab:'production' },
  ];
  return `<section class="panel flat"><div class="between"><div><div class="eyebrow">Deine ersten Schritte</div><h3 class="mt8">Jedes Imperium beginnt klein.</h3></div><button class="icon-button ghost" ${act('dismissTutorial')} aria-label="Einführung ausblenden">${icon('close')}</button></div><div class="tutorial-steps">${steps.map((t,i) => `<div class="tutorial-step ${t.done ? 'done' : ''}"><span class="step-number">${t.done ? icon('check') : i+1}</span><span>${t.text}</span>${!t.done ? `<button ${act('tab',t.tab)}>${icon('arrow')}</button>` : ''}</div>`).join('')}</div></section>`;
}

export function overview(s, ui) {
  const a = assets(s), c = capacity(s), next = TIERS[s.tier + 1], active = Object.values(s.buildings).reduce((n,b) => n + b.active, 0);
  let warnings = [];
  if (s.cash < Math.max(100, c.wages)) warnings.push('<strong>Liquidität knapp.</strong> Waren im Lager bezahlen keine Löhne. Verkaufe Überschüsse oder nutze automatische Verkäufe.');
  if (c.staffing < 0.99) warnings.push('<strong>Personal fehlt.</strong> Wohnquartiere schaffen zusätzliche Arbeitskräfte.');
  if (c.power < 0.99) warnings.push('<strong>Energie fehlt.</strong> Baue Kraftwerke oder Solarparks.');
  if (c.logistics < 0.99) warnings.push('<strong>Transport ausgelastet.</strong> Ein Logistikzentrum erhöht die Kapazität.');
  if (Object.values(s.inventory).some(n => n >= warehouseCapacity(s) * 0.98)) warnings.push('<strong>Lager fast voll.</strong> Verkaufe Waren oder baue Lagerhallen.');
  return `<div class="hero-balance"><div><div class="eyebrow">Verfügbares Kapital ${info('overview')}</div><div class="stat-value number">${preciseCash(s.cash)}</div><div class="stat-sub">${esc(s.name)} · ${TIERS[s.tier].name}</div></div><div class="align-right"><div class="eyebrow">Nettovermögen</div><div class="secondary-value number">${cash(a.total)}</div><div class="stat-sub">inkl. Waren & Buchwerten</div></div></div>${warnings.length ? `<div class="notice">${warnings.join('<br><br>')}<div class="row wrap mt16">${c.staffing<.99||c.power<.99||c.logistics<.99?`<button class="small" ${act('goLab')}>Kapazitäten ausbauen</button>`:''}<button class="small" ${act('tab','market')}>Zum Markt ${icon('arrow')}</button>${s.cash < 100 ? `<button class="small" ${act('liquidate')}>Lager zu Geld machen</button><button class="small" ${act('emergency')}>Notauftrag</button>${info('aid')}${a.total<0?`<button class="small" ${act('restructure')}>Unternehmen sanieren</button>`:''}` : ''}</div></div>` : ''}<div class="dashboard-grid"><section class="panel"><div class="panel-header"><h3>Die Entwicklung deines Unternehmens</h3>${icon('chart')}</div>${chart(s.stats.history.map(h => h.wealth), true, 'Nettovermögen im Verlauf der letzten 96 Spielstunden')}<div class="chart-caption"><span>${s.stats.history.length > 1 ? 'Letzte ' + s.stats.history.length + ' Spielstunden' : 'Deine Geschichte beginnt jetzt'}</span><span>${cash(a.total)}</span></div><div class="metric-grid"><div><small>Cashflow / h</small><strong class="number ${s.stats.lastProfit < 0 ? 'negative' : ''}">${signed(s.stats.lastProfit)}</strong></div><div><small>Produziert</small><strong class="number">${compact(s.stats.produced)}</strong></div><div><small>Aktive Betriebe</small><strong class="number">${number(active)}</strong></div></div><p class="fine-print">Cashflow = Warenumsatz − Einkauf − laufende Kosten der letzten Spielstunde. Ungesicherte Lagerwerte sind kein Umsatz.</p></section><section class="panel"><div class="panel-header"><h3>Dein System</h3>${icon('gear')}</div>${meter('Arbeitskräfte',c.staff,c.workers,'',c.staffing < 1)}${meter('Energie',c.energy,c.availableEnergy,'',c.power < 1)}${meter('Transport',c.freight,c.transport,'',c.logistics < 1)}<div class="between mt24"><span class="muted" style="font-size:11px">Lagerplatz je Ware</span><span class="number">${number(warehouseCapacity(s))}</span></div>${s.tier >= 2 ? `<div class="between mt8"><span class="muted" style="font-size:11px">Umweltbelastung</span><span class="number">${number(c.pollution,1)}</span></div>` : ''}${next ? `<div class="next-era"><div class="divider"></div><div class="between"><span class="eyebrow">Ein neuer Horizont</span><span class="number">${pct(Math.min(1,s.stats.peak/next.wealth),0)}</span></div>${meter('Nächste Entdeckung',s.stats.peak,next.wealth,' €')}<p class="fine-print">Was dahinter liegt, entdeckst du erst, wenn du dort bist.</p></div>` : `<p class="fine-print">Alle Wirtschaftsepochen entdeckt. Wie groß kann dein Unternehmen werden?</p>`}</section>${tutorial(s)}${programmeSummary(s)}<section class="panel"><div class="panel-header"><h3>${s.event ? s.event.name : 'Die Welt um dich herum'}</h3>${icon(s.event?.icon || 'globe')}</div>${s.event ? `<p style="font-size:12px">${esc(s.event.description)}</p><p class="fine-print">Noch ${duration(s.event.end-s.elapsed)} echte Zeit</p>` : `<div class="list-item between"><span class="muted">Konjunktur</span><span>${s.economy.phase}</span></div><div class="list-item between"><span class="muted">Nachfrageindex</span><span class="number">${number(s.economy.cycle*100,1)}</span></div><p class="fine-print">Die Konjunktur bewegt sich in Zyklen. Ereignisse verschieben Angebot, Nachfrage und Kapazitäten.</p>`}<div class="divider"></div><div class="between"><span class="muted" style="font-size:12px">Reputation</span><span class="number">${number(s.reputation)} / 100</span></div><p class="fine-print">Zuverlässige Lieferungen verbessern Gebühren und Kreditbedingungen.</p></section></div>${s.journal.length ? `<div class="subheading"><span>Zuletzt passiert</span><button class="small ghost" ${act('tab','journal')}>Chronik ${icon('arrow')}</button></div><div class="panel flat">${s.journal.slice(0,3).map(j => `<div class="list-item"><p style="color:var(--text);font-size:12px">${esc(j.text)}</p><p>Tag ${Math.floor(j.at/DAY)+1} · ${number(Math.floor(j.at%DAY/HOUR))}:00</p></div>`).join('')}</div>` : ''}`;
}

function assetLabel(name,quote,quantity){
  const available=Number.isFinite(quote.total),value=available?cash(quote.total):'Nicht finanzierbar';
  const explanation=available?`${money(quote.total,2)} Gesamtbaupreis für ${number(quantity)}× ${name}, inklusive fehlender Baustoffe`:'Der Baupreis ist nicht finanzierbar.';
  return `<div class="asset-label"><h3>${esc(name)}</h3><small class="asset-price number" title="${esc(explanation)}" aria-label="${esc(explanation)}">${value}${quantity>1?` · ${number(quantity)}×`:''}</small></div>`;
}

function buildingCard(s, ui, id) {
  const b=BUILDINGS[id],own=s.buildings[id],q=buildQuote(s,id,ui.qty);
  return `<article class="compact-asset" data-key="building:${id}" data-building="${id}"><div class="asset-name">${icon(b.icon)}${assetLabel(b.name,q,ui.qty)}${info('building:'+id)}</div><span class="asset-count number" title="${own.active} aktiv · Ausbau ${own.level}">${number(own.count)}<small class="${own.level?'':'empty-level'}">×${2**own.level}</small></span><div class="asset-controls"><button ${repeat} ${act('demolish',id)} aria-label="${ui.qty} ${b.name} abbauen"${disabled(own.count<ui.qty)}>−${number(ui.qty)}</button><button class="primary" ${repeat} ${act('build',id)} title="${cash(q.total)} inklusive fehlender Baustoffe" aria-label="${ui.qty} ${b.name} bauen für ${cash(q.total)}"${disabled(!Number.isFinite(q.total)||s.cash+1e-7<q.total||own.count+ui.qty>10000)}>+${number(ui.qty)}</button></div></article>`;
}

export function buildingDetails(s,ui,id){
  const b=BUILDINGS[id],own=s.buildings[id],rate=buildingRate(s,id),q=buildQuote(s,id,ui.qty);
  const state=!own.count?'Noch nicht gebaut':!own.active?'Pausiert':rate.guarded?'Marge zu niedrig':rate.storage<.99?'Lager begrenzt':rate.cash<.99?'Liquidität begrenzt':rate.global<.99?'Kapazität begrenzt':rate.supply<.99?'Vorprodukt fehlt':'In Produktion';
  return `<div data-building-details="${id}"><div class="between"><span class="status-tag">${state}</span><strong class="number">${number(own.active)} / ${number(own.count)} aktiv</strong></div><div class="recipe">${Object.entries(b.input).map(([r,n])=>resource(r,n*rate.mult)).join(' + ')||'<span>Rohstoffgewinnung</span>'}${icon('arrow')}${Object.entries(b.output).map(([r,n])=>resource(r,n*rate.mult)).join(' + ')}<small>/ h je Betrieb</small></div><div class="detail-grid"><p>Auslastung<strong>${pct(rate.utilization,1)}</strong></p><p>Indikative Marge / h / Betrieb<strong>${signed(rate.margin)}</strong></p><p>Personal je Betrieb<strong>${number(b.staff*Math.pow(.92,s.research.automation),1)}</strong></p><p>Energie · Transport<strong>${b.energy} · ${b.freight}</strong></p><p>Lohn / h / Betrieb<strong>${money(b.wage*(1+own.level*.08)*POLICIES[s.policy].wage,2)}</strong></p><p>Baupreis für ${number(ui.qty)}<strong>${cash(q.total)}</strong></p></div><div class="row wrap"><button class="small" ${act('preview',id)}>Bau prüfen</button><button class="small" ${act('showChain',id)}>Produktionskette</button><button class="small" ${act('bulkBuild',id)}>Max. bauen</button><button class="small" ${act('bulkDemolish',id)}${disabled(!own.count)}>Alle abbauen</button></div>${own.count?`<div class="row wrap mt8"><button ${repeat} class="small" ${act('active',id)} data-delta="-${ui.qty}"${disabled(!own.active)}>−${number(ui.qty)} aktiv</button><button ${repeat} class="small" ${act('active',id)} data-delta="${ui.qty}"${disabled(own.active===own.count)}>+${number(ui.qty)} aktiv</button><button class="small" ${act('pause',id)}>${own.active?'Alle pausieren':'Alle starten'}</button></div><button class="wfull mt8" ${act('upgrade',id)}${disabled(own.level>=5||s.cash<upgradeQuote(s,id))}>${own.level>=5?'Voll ausgebaut':`Ausbau ${own.level+1} · ×2 Produktion · ${cash(upgradeQuote(s,id))}`}</button>${Object.keys(b.input).length?`<button class="wfull mt8" ${act('setupSupplies',id)}>Vorprodukt-Einkauf einrichten</button>`:''}`:''}</div>`;
}

function infrastructure(s,ui){
  return `<div class="asset-list">${Object.entries(INFRA).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>{const q=buildQuote(s,id,ui.qty,true);return `<article class="compact-asset" data-key="infra:${id}"><div class="asset-name">${icon(d.icon)}${assetLabel(d.name,q,ui.qty)}${info('infra:'+id)}</div><span class="asset-count number">${number(s.infra[id])}</span><div class="asset-controls"><button ${repeat} ${act('demolishInfra',id)} aria-label="${ui.qty} ${d.name} abbauen"${disabled(s.infra[id]<ui.qty)}>−${number(ui.qty)}</button><button ${repeat} class="primary" ${act('buildInfra',id)} title="${cash(q.total)}" aria-label="${ui.qty} ${d.name} bauen für ${cash(q.total)}"${disabled(!Number.isFinite(q.total)||q.total>s.cash||s.infra[id]+ui.qty>10000)}>+${number(ui.qty)}</button></div></article>`;}).join('')}</div>`;
}

function chainsView(s,ui){
  const blueprint=chainBlueprint(s,ui.chain),ids=Object.keys(BUILDINGS).filter(id=>BUILDINGS[id].tier<=s.tier);
  const depth=Math.max(...blueprint.nodes.map(n=>n.depth));
  return `<div class="toolbar"><label class="chain-selector">Produktionskette<select data-setting="chain">${ids.map(id=>`<option value="${id}"${id===ui.chain?' selected':''}>${BUILDINGS[id].name} → ${Object.keys(BUILDINGS[id].output).map(r=>RESOURCES[r].name).join(', ')}</option>`).join('')}</select></label>${info('chains')}</div><section class="panel chain-panel"><div class="between"><h3>${BUILDINGS[ui.chain].name}</h3><span class="eyebrow">Exaktes Grundverhältnis</span></div><p class="chain-note">${blueprint.output.map(r=>`${number(r.amount)} ${RESOURCES[r.resource].name}`).join(' + ')} pro Spielstunde · ohne Boni und Engpässe</p><div class="chain-scroll" tabindex="0" role="region" aria-label="Produktionskette von Rohstoffen zum Endprodukt"><div class="chain-diagram">${Array.from({length:depth+1},(_,level)=>`<div class="chain-stage"><div class="eyebrow">${level===0?'Rohstoffe':level===depth?'Endprodukt':'Verarbeitung'}</div>${blueprint.nodes.filter(n=>n.depth===level).map(node=>`<div class="chain-node${node.id===ui.chain?' final-node':''}"><div class="row gap8">${icon(BUILDINGS[node.id].icon)}<strong>${number(node.count)}× ${BUILDINGS[node.id].name}</strong>${info('building:'+node.id)}</div><div class="chain-products">${Object.entries(BUILDINGS[node.id].output).map(([r,q])=>`${number(q*node.count)} ${RESOURCES[r].name} / h`).join(' + ')}</div>${Object.keys(BUILDINGS[node.id].input).length?`<small>← ${Object.entries(BUILDINGS[node.id].input).map(([r,q])=>`${number(q*node.count)} ${RESOURCES[r].name}`).join(' + ')}</small>`:''}</div>`).join('')}</div>${level<depth?`<div class="chain-arrow" aria-hidden="true">${icon('arrow')}</div>`:''}`).join('')}</div></div><details data-preserve-open><summary>Alle Materialverbindungen · ${blueprint.edges.length}</summary><div class="chain-connections">${blueprint.edges.map(e=>`<div>${BUILDINGS[e.from].name} ${icon('arrow')} <strong>${number(e.amount)} ${RESOURCES[e.resource].name} / h</strong> ${icon('arrow')} ${BUILDINGS[e.to].name}</div>`).join('')||'<p>Rohstoffgewinnung ohne Vorprodukte.</p>'}</div></details><p class="chain-note">Gemeinsame Zulieferer sind zusammengefasst. Ausbau, Forschung und Strategie verändern die Live-Mengen; die Mengenplanung berücksichtigt deine aktuellen Boni.</p></section><details class="panel mt16" data-preserve-open><summary>Eigene Mengenplanung anzeigen</summary>${plannerView(s)}</details>`;
}


function strategy(s) {
  return `${s.tier>=2?`<section class="panel mt16" style="margin-bottom:20px"><div class="between"><h3>Margenwächter ${info('profitGuard')}</h3><button class="small ${s.profitGuard?'primary':''}" ${act('profitGuard')}>${s.profitGuard?'Aktiv':'Inaktiv'}</button></div></section>`:''}<div class="grid2">${Object.entries(POLICIES).filter(([id])=> id !== 'green' || s.tier >= 2).map(([id,p]) => `<section class="panel"><div class="between"><h3>${p.name} ${info('policy:'+id)}</h3>${s.policy===id ? icon('check') : ''}</div><p class="details-copy">${p.description}</p><button class="wfull mt24 ${s.policy===id?'primary':''}" ${act('policy',id)}${disabled(s.policy===id)}>${s.policy===id?'Aktive Strategie':'Strategie wählen'}</button></section>`).join('')}</div><section class="panel mt24"><h3>Reihenfolge der Produktion</h3><p class="mt8" style="font-size:12px">Bei knappen Vorprodukten entscheidet die Reihenfolge, welcher Betrieb zuerst bedient wird.</p><div class="segmented mt16"><button ${act('priority','balanced')} class="${s.priority==='balanced'?'active':''}">Von Rohstoff zu Produkt</button><button ${act('priority','advanced')} class="${s.priority==='advanced'?'active':''}">Höchste Veredelung zuerst</button></div></section>`;
}

export function production(s,ui) {
  normalizeUI(ui,s);
  const sub = ui.productionTab;
  const ids = Object.keys(BUILDINGS).filter(id => BUILDINGS[id].tier <= s.tier && (ui.buildFilter !== 'owned' || s.buildings[id].count > 0) && (ui.buildFilter !== 'raw' || !Object.keys(BUILDINGS[id].input).length));
  return `${head('Wertschöpfung','Etwas erschaffen.','Baue Kapazitäten. Verbinde Rohstoffe mit Ideen.')}<div class="toolbar sticky-controls production-controls"><div class="segmented">${[['business','Betriebe'],['infra','Infrastruktur'],['chains','Ketten'],['planner','Planung'],...(s.tier>=1?[['strategy','Strategie']]:[])].map(([id,name])=>`<button ${act('productionTab',id)} class="${sub===id?'active':''}">${name}</button>`).join('')}</div>${['business','infra'].includes(sub)?quantity(ui):''}</div>${sub==='business'?`<div class="toolbar production-summary"><span class="muted production-balance" style="font-size:11px">${number(Object.values(s.buildings).reduce((n,b)=>n+b.count,0))} Betriebe · ${preciseCash(s.cash)} verfügbar</span><select data-setting="buildFilter" aria-label="Betriebe filtern"><option value="all" ${ui.buildFilter==='all'?'selected':''}>Alle bekannten Betriebe</option><option value="owned" ${ui.buildFilter==='owned'?'selected':''}>Meine Betriebe</option><option value="raw" ${ui.buildFilter==='raw'?'selected':''}>Rohstoffgewinnung</option></select></div><div class="asset-list">${ids.map(id=>buildingCard(s,ui,id)).join('')}</div>${!ids.length?empty('Noch ist es still.','Baue deinen ersten Betrieb in der Ansicht „Alle bekannten Betriebe“.','factory'):''}`:sub==='infra'?infrastructure(s,ui):sub==='chains'?chainsView(s,ui):sub==='planner'?plannerView(s,ui):strategy(s)}${s.tier<TIERS.length-1 && ['business','infra'].includes(sub)?`<div class="locked-card mt24">${icon('compass')}<div><h3>Die Welt ist größer, als sie scheint.</h3><p>Wachse weiter. Neue Möglichkeiten erscheinen, wenn du bereit bist.</p></div></div>`:''}`;
}

export function buildingPreview(plan){
  const b=BUILDINGS[plan.id],metricNames={staff:'Arbeitskräfte',energy:'Energie',freight:'Transport'};
  const cost=value=>value===null?'Nicht finanzierbar':cash(value);
  const warnings=[];
  if(!plan.withinLimit)warnings.push('Das Limit von 10.000 Betrieben dieses Typs würde überschritten.');
  else if(!plan.affordable)warnings.push(plan.missingCash===null?'Dieser Bau ist nicht finanzierbar.':`Es fehlen ${cash(plan.missingCash)} für den Bau.`);
  if(plan.affectsExisting){
    const before=pct(plan.utilizationBefore,1),after=pct(plan.utilizationAfter,1);
    warnings.push(before===after?`Die technische Auslastung sinkt geringfügig (auf rund ${after}). Das betrifft auch bestehende Betriebe.`:`Die technische Auslastung sinkt von ${before} auf ${after}. Das betrifft auch bestehende Betriebe.`);
  }
  if(plan.lowReserve)warnings.push('Nach dem Bau bleibt weniger als eine Reserve für zwei Spielstunden der zusätzlichen laufenden Kosten.');
  if(plan.guarded)warnings.push('Der Margenwächter würde diesen Betrieb bei den aktuellen Kursen anhalten.');
  return `<div class="cash-control mt24"><div class="between wfull"><span class="muted">Zusätzliche Betriebe</span><output class="number" style="font-size:28px">${plan.quantity}</output></div><div class="cash-buttons wfull">${[-100,-10,-1,1,10,100].map(delta=>`<button ${act('previewQuantity',plan.id)} data-delta="${delta}"${disabled(delta<0?plan.quantity===1:plan.quantity===10000)}>${delta>0?'+':'−'}${Math.abs(delta)}</button>`).join('')}</div></div>${warnings.length?`<div class="notice">${warnings.map(esc).join('<br><br>')}</div>`:''}<div class="detail-grid"><p>Gesamter Baupreis<strong class="number">${cost(plan.cost)}</strong></p><p>Nach Bau, ohne Prämien<strong class="number">${cash(plan.cashAfter)}</strong></p><p>Löhne / h bei Volllast<strong class="number">${cash(plan.wages)}</strong></p><p>Deckungsbeitrag / h vor Steuer<strong class="number">${signed(plan.capacityMargin)}</strong></p></div><div class="preview-recipe"><span class="eyebrow">Zusätzliche Sollmengen / h</span><div class="recipe mt8">${plan.inputs.map(r=>resource(r.id,r.quantity)).join(' + ')||'<span>Rohstoffgewinnung</span>'}${icon('arrow')}${plan.outputs.map(r=>resource(r.id,r.quantity)).join(' + ')}</div></div><details class="preview-section"${plan.deficits.length?' open':''}><summary>Gesamtkapazitäten · ${plan.deficits.length?`${plan.deficits.length} ${plan.deficits.length===1?'Engpass':'Engpässe'}`:'ausreichend'}</summary><p>Gesamtes Unternehmen nach dem Bau; bereits bestehende Engpässe sind enthalten.</p><div class="detail-grid mt16">${Object.entries(plan.capacity).map(([key,c])=>`<p>${metricNames[key]} nach dem Bau<strong class="number">${number(c.used,1)} / ${number(c.available,1)}</strong></p>`).join('')}<p>Technische Auslastung<strong class="number">${pct(plan.utilizationAfter,0)}</strong></p></div>${plan.deficits.map(d=>`<div class="preview-supply"><strong>${metricNames[d.metric]}: ${number(d.shortage,1)} fehlen</strong><p>${d.additionalShortage>1e-9?`${number(d.additionalShortage,1)} zusätzlich durch diesen Bau`:'Bereits bestehender Engpass'}</p><p>${d.options.length?d.options.map(o=>`${o.quantity}× ${INFRA[o.id].name} · ${o.withinLimit?cost(o.cost):'Baulimit überschritten'}`).join('<br>oder '):'Eine passende Erweiterung wurde noch nicht entdeckt.'}</p></div>`).join('')}${plan.capacity.energy.availableNow<plan.capacity.energy.available-1e-7?`<p class="mt8 muted">Mit dem aktuellen Kohlevorrat stehen momentan ${number(plan.capacity.energy.availableNow,1)} Energie zur Verfügung. Der technische Wert setzt Brennstoffversorgung voraus.</p>`:''}</details>${plan.supplies.length?`<details class="preview-section"${plan.supplies.some(r=>r.gap>0)?' open':''}><summary>Zulieferung · ${plan.supplies.filter(r=>r.gap>0).length} ungedeckte Ware${plan.supplies.filter(r=>r.gap>0).length===1?'':'n'}</summary>${plan.supplies.map(r=>`<div class="preview-supply"><div class="between"><strong>${RESOURCES[r.id].name}</strong><span class="number">${number(r.needed,1)} / h zusätzlich</span></div><p>${number(r.stock,1)} im Lager nach dem Bau · ${r.gap>0?`${number(r.gap,1)} / h fehlen dem gesamten Unternehmen`: 'Eigene Sollproduktion deckt den Gesamtbedarf.'}</p>${r.gap>0?`<p>${r.producer?`Alternative zum Markteinkauf: mindestens ${r.additionalProducers}× ${BUILDINGS[r.producer].name} zusätzlich bei Volllast.`:'Markteinkauf einplanen.'}</p>`:''}</div>`).join('')}</details>`:''}${plan.materials.length?`<details class="preview-section"><summary>Baustoffe · ${cost(plan.materialCost)} Einkauf enthalten</summary>${plan.materials.map(r=>`<div class="preview-supply"><strong>${RESOURCES[r.id].name} · ${number(r.needed)}</strong><p>${number(r.fromStock,1)} aus dem Lager · ${number(r.purchased,1)} werden beim Bau gekauft</p></div>`).join('')}</details>`:''}<details class="preview-section"><summary>${icon('info')} Rechenregeln & Annahmen</summary><p>Eine Spielstunde dauert eine echte Minute. Die Vorschau verwendet aktuelle Kurse, bekannte Rezepte und deine Live-Boni. Zusätzliche Offline-Boni sind nicht eingerechnet. Der Deckungsbeitrag bewertet alle Ausgänge als Marktverkauf und alle Vorprodukte als Markteinkauf, einschließlich Spanne und Gebühren. Löhne, zusätzlicher Brennstoff und zusätzliche Umweltabgaben sind abgezogen. Die technische Auslastung begrenzt den angezeigten Betrag.</p><p>Vorprodukte, freier Lagerplatz und Betriebskapital müssen vorhanden sein. Zulieferer werden mit Volllast gerechnet; deren eigene Vorprodukte und Kapazitäten sind zusätzlich zu planen. Die vorgeschlagenen Erweiterungen sind nicht Teil des angezeigten Baupreises. Bestehende Betriebe können durch neue Engpässe langsamer werden.</p><p>Steuern, Kreditzinsen, Mengen-Preiseffekte, Erfolgsprämien und zukünftige Marktänderungen sind nicht vorhergesagt. ${plan.paybackSeconds!==null?`Rechnerische Amortisation nur dieses Baupreises: ${duration(plan.paybackSeconds)} echte Zeit bei unverändertem Deckungsbeitrag. Das ist keine Gewinnzusage.`:'Bei dieser Versorgung und Bewertung ist keine rechnerische Amortisation gegeben.'} Der tatsächliche Bau wird beim Bestätigen neu zum dann gültigen Preis geprüft.</p></details>`;
}

function marketItem(s,ui,id) {
  const d=RESOURCES[id], p=price(s,id), m=s.market[id], a=s.automation[id], buy=quote(s,id,ui.qty,'buy'), sell=quote(s,id,ui.qty,'sell'), expanded=ui.open.has(`m-${id}`), change=(p/m.previous-1);
  const autoNames={off:'Manuell',sell:'Überschüsse verkaufen',buy:'Vorräte auffüllen',both:'Einkauf & Verkauf'};
  return `<article class="market-item" data-key="resource:${id}"><div class="market-row"><div class="row market-name">${icon(d.icon)}<div><strong>${d.name} ${info('resource:'+id)}</strong></div></div><div class="market-price number">${money(p,2)}<small>${change>=0?'+':''}${pct(change,1)} / h</small></div>${chart([...m.history.slice(-47),p],false,`${d.name}: Preisverlauf`)}<div class="market-stock number">${number(s.inventory[id],1)}<small>von ${compact(warehouseCapacity(s))} im Lager</small></div><div class="market-actions"><button aria-label="${number(ui.qty)} ${d.name} verkaufen für ${preciseCash(sell.total)}" ${repeat} title="${cash(sell.total)} Erlös" ${act('trade',id)} data-side="sell"${disabled(s.inventory[id]+1e-7<ui.qty)}>−${number(ui.qty)}</button><button aria-label="${number(ui.qty)} ${d.name} kaufen für ${preciseCash(buy.total)}" ${repeat} title="${cash(buy.total)} Kaufpreis" ${act('trade',id)} data-side="buy"${disabled(s.cash+1e-7<buy.total || s.inventory[id]+ui.qty>warehouseCapacity(s))}>+${number(ui.qty)}</button><button class="all-button" ${act('tradeAll',id)} data-side="sell" aria-label="Alle ${d.name} verkaufen"${disabled(s.inventory[id]<1e-7)}>Alle −</button><button class="all-button" ${act('tradeAll',id)} data-side="buy" aria-label="Maximal ${d.name} kaufen"${disabled(s.cash<=0||s.inventory[id]>=warehouseCapacity(s))}>Alle +</button></div></div><div class="market-auto"><span>${a.mode!=='off'?icon('refresh'):''} ${autoNames[a.mode]}</span><button ${act('expand',`m-${id}`)} aria-expanded="${expanded}">Automatik${s.tier>=1?' & Limit':''} ${icon(expanded?'minus':'plus')}</button></div>${expanded?`<div class="market-detail"><div class="auto-form"><div><label for="auto-${id}">Automatik</label><select id="auto-${id}" data-auto="${id}" data-field="mode">${Object.entries(autoNames).map(([v,n])=>`<option value="${v}"${a.mode===v?' selected':''}>${n}</option>`).join('')}</select></div><div><label for="low-${id}">Nachkaufen unter</label><div class="input-stepper"><button ${act('autoStep',id)} data-field="low" data-delta="-${ui.qty}" aria-label="Einkaufsschwelle senken">−</button><input id="low-${id}" type="number" inputmode="numeric" min="0" max="1000000000" value="${a.low}" data-auto="${id}" data-field="low"><button ${act('autoStep',id)} data-field="low" data-delta="${ui.qty}" aria-label="Einkaufsschwelle erhöhen">+</button></div></div><div><label for="high-${id}">Verkaufen über</label><div class="input-stepper"><button ${act('autoStep',id)} data-field="high" data-delta="-${ui.qty}" aria-label="Verkaufsschwelle senken">−</button><input id="high-${id}" type="number" inputmode="numeric" min="0" max="1000000000" value="${a.high}" data-auto="${id}" data-field="high"><button ${act('autoStep',id)} data-field="high" data-delta="${ui.qty}" aria-label="Verkaufsschwelle erhöhen">+</button></div></div></div><p class="fine-print">Die Automatik hält eine Lohnreserve zurück. Einkaufsschwelle ≤ Verkaufsschwelle. Für eigene Vorprodukte eine Reserve behalten, damit die Verarbeitung weiterläuft. Preise und Gebühren gelten auch automatisch.</p>${s.tier>=1?`<div class="divider"></div><button class="small" ${act('orderDialog',id)}>${icon('chart')} Limitauftrag anlegen</button>`:''}</div>`:''}</article>`;
}

export function market(s,ui) {
  const ids=Object.keys(RESOURCES).filter(id=>RESOURCES[id].tier<=s.tier && (ui.marketFilter!=='auto'||s.automation[id].mode!=='off'));
  return `${head('Angebot & Nachfrage','Alles hat seinen Preis.','Preise reagieren auf Knappheit, Konjunktur und deine Handelsmengen.')}<div class="toolbar sticky-controls"><div class="segmented">${[['all','Alle Waren'],['auto','Automatik']].map(([id,n])=>`<button ${act('marketFilter',id)} class="${ui.marketFilter===id?'active':''}">${n}</button>`).join('')}</div>${quantity(ui)}<button class="small" ${act('liquidate')}>Lager verkaufen</button></div><div class="market-head"><span>Ware</span><span>Mittelkurs</span><span>48 Stunden</span><span>Lager</span><span class="align-right">Handel für ${ui.qty}</span></div>${ids.map(id=>marketItem(s,ui,id)).join('')}${!ids.length?empty('Keine Waren in dieser Ansicht.','Wähle einen anderen Filter oder richte eine Automatik ein.','market'):''}<p class="fine-print">Kauf- und Verkaufsschaltflächen handeln ${ui.qty} Einheiten inklusive Gebühren und Preiseffekt. Der genaue Gesamtbetrag steht im Info-Dialog und beim Zeigen auf den Knopf. Der Mittelkurs ist ein Referenzpreis. Große Aufträge bewegen den Markt.</p>${s.orders.length?`<div class="subheading">Aktive Limitaufträge <span class="muted">${s.orders.length} / 20</span></div><div class="panel">${s.orders.map(o=>`<div class="list-item between"><div><h3 style="font-size:12px">${o.side==='buy'?'Kaufe':'Verkaufe'} ${o.quantity} ${RESOURCES[o.resource].name}</h3><p>${o.side==='buy'?'Höchstens':'Mindestens'} ${money(o.limit,2)} / Stück inkl. Gebühren</p></div><button class="small" ${act('cancelOrder',o.id)}>Löschen</button></div>`).join('')}</div>`:''}`;
}

function amountControl(ui) {
  return `<div class="cash-control"><div class="row"><div><label for="finance-amount">Betrag pro Transaktion</label></div><div class="row gap8"><input id="finance-amount" type="number" min="1" max="100000000000000" inputmode="numeric" value="${ui.amount}" data-setting="amount" class="number" aria-label="Transaktionsbetrag in Euro"><span class="muted">€</span></div></div><div class="cash-buttons">${[-10,-1,1,10].map(n=>`<button ${repeat} ${act('amount',n)}>${n>0?'+':'−'}${Math.abs(n)}</button>`).join('')}<button ${act('amountScale',.1)}>÷10</button><button ${act('amountScale',10)}>×10</button></div></div>`;
}

function banks(s,ui) {
  return `<div class="grid2">${Object.entries(BANKS).map(([id,b])=>`<section class="panel bank-card"><div class="between bank-heading"><h3>${icon(b.icon)} ${b.name} ${info('bank:'+id)}</h3><strong class="bank-value number">${preciseCash(s.banks[id])}</strong></div><div class="rate"><strong>${pct(bankRate(s,id),3)}</strong> Zins pro Spieltag · vor 15 % Steuer</div><p class="fine-print">${b.description}</p><div class="bank-actions"><button ${repeat} ${act('bank',id)} data-side="withdraw"${disabled(s.banks[id]<ui.amount)}>Abheben</button><button class="primary" ${repeat} ${act('bank',id)} data-side="deposit"${disabled(s.cash<ui.amount)}>Einzahlen</button><button class="all-button" ${act('bankAll',id)} data-side="withdraw"${disabled(!s.banks[id])}>Alles abheben</button><button class="all-button" ${act('bankAll',id)} data-side="deposit"${disabled(!s.cash)}>Alles einzahlen</button></div></section>`).join('')}<section class="panel bank-card"><div class="between"><h3>Festgeld ${info('fixed')}</h3>${icon('clock')}</div><p class="mt16 muted" style="font-size:11px">Gebunden · ab 500 €</p><label for="fixed-days" class="mt16">Laufzeit wählen</label><select id="fixed-days" class="wfull" data-setting="fixedDays">${[[10,.003],[20,.0038],[60,.0048]].filter(([days])=>days<=20||s.tier>=2).map(([d,r])=>`<option value="${d}"${ui.fixedDays===d?' selected':''}>${d} Spieltage · ${duration(d*DAY)} echt · ${pct(r,2)} / Tag</option>`).join('')}</select><button class="wfull mt16" ${act('fixed')}${disabled(ui.amount<500||ui.amount>s.cash)}>Festgeld anlegen · ${cash(ui.amount)}</button></section><section class="panel bank-card"><div class="between"><h3>Kontokorrent ${info('credit')}</h3>${icon('bank')}</div><div class="bank-value number">${cash(s.debt)}</div><div class="rate">Schuld · <strong>${pct(debtRate(s),3)}</strong> Zins pro Spieltag</div><div class="rate mt8">Kreditrahmen: <strong>${cash(creditLimit(s))}</strong></div><p class="fine-print">Gemeinsamer Kreditrahmen: ${cash(creditLimit(s))}. Variable Zinsen. Nicht zahlbare Zinsen erhöhen die Schuld. Überziehung senkt täglich die Reputation.</p><div class="bank-actions"><button ${act('repay')}${disabled(ui.amount>s.cash||ui.amount>s.debt)}>Tilgen</button><button ${act('borrow')}${disabled(ui.amount+s.debt+s.loans.reduce((n,l)=>n+l.principal,0)>creditLimit(s))}>Aufnehmen</button></div>${s.tier>=2?`<div class="divider"></div><h3>Investitionskredit ${info('credit')}</h3><p class="fine-print">Fester Zins bei Abschluss: ${pct(debtRate(s)*.8,3)} / Tag. Zehn gleiche Tilgungsraten alle zehn Spieltage. Bei fehlendem Geld wird die Rate ins Kontokorrent umgebucht (−4 Reputation).</p><button class="wfull mt16" ${act('termLoan')}${disabled(s.loans.length>=5||ui.amount+s.debt+s.loans.reduce((n,l)=>n+l.principal,0)>creditLimit(s))}>Investitionskredit aufnehmen</button>`:''}</section></div>${s.loans.length?`<div class="subheading">Laufende Investitionskredite</div><div class="panel">${s.loans.map(l=>`<div class="list-item between"><div><h3>${cash(l.principal)} Restschuld</h3><p>${pct(l.rate,3)} / Tag · nächste Rate ${cash(Math.min(l.principal,l.original/10))} in ${duration(l.nextPayment-s.elapsed)}</p></div><button class="small" ${act('repayLoan',l.id)}${disabled(ui.amount>l.principal||ui.amount>s.cash)}>Sondertilgen</button></div>`).join('')}</div>`:''}<p class="fine-print">Ein Spieltag dauert 24 echte Minuten. Alle Zinssätze beziehen sich auf diese Spieltage. Zinsen und Dividenden unterliegen 15 % Kapitalertragsteuer. Bankkapital ist Teil deines Vermögens.</p>`;
}

function stocks(s,ui) {
  if(s._firm?.world)return `<section class="panel"><p>Börsenbeteiligungen verwaltest du in der Holding oder einer eigenen Investmentgesellschaft.</p><button ${act('holdingStocks')}>Holdingdepot öffnen</button></section>`;
  return `<div class="toolbar"><span class="muted" style="font-size:11px">${cash(assets(s).securities)} Depotwert</span></div>${Object.entries(STOCKS).filter(([id])=>id!=='index'&&C.company(s._holding||s,id)?.listed).map(([id,d])=>{
    const p=s.stocks[id],change=p.price/p.previous-1,gain=p.price*p.quantity-p.basis,expanded=ui.open.has(`s-${id}`);
    return `<article class="stock-card" data-key="stock:${id}"><div class="stock-row"><div><div class="stock-name">${d.name} ${info('stock:'+id)}</div><p>${d.full}</p></div>${chart([...p.history.slice(-47),p.price],false,`${d.name}: Kursverlauf`)}<div class="number">${money(p.price,2)}<small>${change>=0?'+':''}${pct(change,2)} / h</small></div><div class="stock-position"><span class="number">${p.quantity}</span><small>Anteile · ${signed(gain)} Buchgewinn</small></div><div class="market-actions"><button ${repeat} ${act('stock',id)} data-side="sell"${disabled(p.quantity<ui.qty)}>−${ui.qty}</button><button ${repeat} ${act('stock',id)} data-side="buy"${disabled(p.price*ui.qty*1.005>s.cash)}>+${number(ui.qty)}</button><button class="all-button" ${act('stockAll',id)} data-side="sell"${disabled(!p.quantity)}>Alle −</button><button class="all-button" ${act('stockAll',id)} data-side="buy"${disabled(p.price*1.005>s.cash)}>Alle +</button></div></div><div class="card-footer"><span>${money(p.report.dps,3)} Dividende / Anteil / Tag</span><button ${act('expand',`s-${id}`)} aria-expanded="${expanded}">Geschäftsbericht ${icon(expanded?'minus':'plus')}</button></div>${expanded?stockAnalysis(s,id):''}</article>`;
  }).join('')}`;
}

function bonds(s,ui) {
  const holding=s._holding||s,issuer=ui.bondIssuer||'ferrum',q=C.loanQuote(holding,issuer);
  const companyBond=s.tier>=2?`<section class="panel mt16"><h3>Anleihe eines echten Unternehmens</h3><p>Finanziere Anlagen und Betriebskapital eines konkreten Schuldners. Zinsen kommen aus seiner Kasse; fehlende Zahlungen können zum Verlust führen.</p><label class="mt16" for="bond-issuer">Emittent</label><select id="bond-issuer" data-setting="bondIssuer">${holding.group.companies.filter(c=>c.world).map(c=>`<option value="${c.id}"${c.id===issuer?' selected':''}>${esc(c.name)}</option>`).join('')}</select><div class="detail-grid mt16"><p>Zins / Spieltag<strong>${pct(q.rate+.001,2)}</strong></p><p>Freier Finanzierungsrahmen<strong>${cash(q.limit)}</strong></p><p>Kapitalrückzahlung<strong>10 Spieltage · ${duration(10*DAY)}</strong></p></div><button class="mt16" ${act('companyBond')}${disabled(ui.amount>s.cash||ui.amount>q.limit)}>Unternehmensanleihe zeichnen · ${cash(ui.amount)}</button></section>`:'';
  return `<div class="grid3">${Object.entries(BONDS).filter(([id])=>id==='state'||id==='municipal'&&s.tier>=2).map(([id,b])=>`<section class="panel financial-card">${icon(id==='state'?'shield':id==='municipal'?'building':'factory')}<h3>${b.name} ${info('bond:'+id)}</h3><p>${b.days} Spieltage · ${b.risk?pct(b.risk,0)+' Ausfallrisiko':'garantiert'}</p><div class="finance-facts"><div><small>Zins / Spieltag</small><strong class="number">${pct(b.rate,2)}</strong></div><div><small>Echte Laufzeit</small><strong class="number">${duration(b.days*DAY)}</strong></div></div><p>Mindestanlage ${cash(b.min)}. Kapital bis Fälligkeit gebunden.</p><button class="wfull" ${act('bond',id)}${disabled(ui.amount<b.min||ui.amount>s.cash||s.bonds.length>=30)}>Zeichnen · ${cash(ui.amount)}</button></section>`).join('')}</div>${companyBond}<p class="fine-print">Risikowerte gelten pro Anleihe bei Fälligkeit. Staatsanleihen sind garantiert. Unternehmensanleihen hängen von tatsächlichen Sicherheiten und Zahlungen des Emittenten ab. Rückzahlung und Nettozinsen erfolgen automatisch.</p>`;
}

function ventures(s,ui) {
  const holding=s._holding||s;
  return `<section class="panel"><h3>Beteiligungen an echten Unternehmen</h3><p class="mt16">Verhandle mit privaten Eigentümern, prüfe die Bilanz und erwirb Einfluss bis zur vollständigen Übernahme.</p><button class="primary mt16" ${act('tab','companies')}>Unternehmensmarkt öffnen</button></section>`;
}

function treasuryView(s,ui){
  if(s.tier<2)return '';
  const t=s.treasury;
  return `<section class="panel mt24"><div class="between"><h3>Liquiditätsmanager ${info('treasury')}</h3><button class="small ${t.enabled?'primary':''}" ${act('treasuryToggle')}>${t.enabled?'Aktiv':'Inaktiv'}</button></div><div class="auto-form mt16"><div><label for="treasury-bank">Reservekonto</label><select id="treasury-bank" data-treasury="bank" class="wfull">${Object.entries(BANKS).map(([id,b])=>`<option value="${id}"${t.bank===id?' selected':''}>${b.name}</option>`).join('')}</select></div>${[['floor','Mindestreserve'],['target','Ziel in der Kasse']].map(([field,name])=>`<div><label for="treasury-${field}">${name}</label><div class="input-stepper"><button ${act('treasuryStep',field)} data-delta="-${ui.amount}" aria-label="${name} um ${ui.amount} senken">−</button><input type="number" inputmode="numeric" id="treasury-${field}" value="${t[field]}" min="50" max="1000000000000" data-treasury="${field}"><button ${act('treasuryStep',field)} data-delta="${ui.amount}" aria-label="${name} um ${ui.amount} erhöhen">+</button></div></div>`).join('')}</div></section>`;
}

function bankPlansView(s,ui){
  return `<section class="panel mt16"><div class="between"><h3>Spar- & Auszahlungspläne ${info('bankPlans')}</h3><span class="eyebrow">${s.bankPlans.length} / 12</span></div><div class="auto-form mt8"><div><label for="bank-plan-product">Produkt</label><select id="bank-plan-product" data-setting="bankPlanProduct">${[...Object.entries(BANKS).map(([id,b])=>[id,b.name]),['fixed','Festgeld']].map(([id,name])=>`<option value="${id}"${ui.bankPlanProduct===id?' selected':''}>${name}</option>`).join('')}</select></div><div><label for="bank-plan-direction">Richtung</label><select id="bank-plan-direction" data-setting="bankPlanDirection"><option value="deposit"${ui.bankPlanDirection==='deposit'?' selected':''}>Sparen</option>${ui.bankPlanProduct!=='fixed'?`<option value="withdraw"${ui.bankPlanDirection==='withdraw'?' selected':''}>Auszahlen</option>`:''}</select></div><div><label for="bank-plan-period">Abstand</label><select id="bank-plan-period" data-setting="planPeriod">${[1,5,10].map(n=>`<option value="${n}"${ui.planPeriod===n?' selected':''}>${n} Spieltag${n===1?'':'e'}</option>`).join('')}</select></div></div><div class="between wrap mt8"><span class="muted">Rate ${cash(ui.amount)}${ui.bankPlanProduct==='fixed'?` · ${ui.fixedDays} Tage Laufzeit`:''}</span><button class="small" ${act('createBankPlan')}${disabled(ui.amount<(ui.bankPlanProduct==='fixed'?500:10)||s.bankPlans.length>=12||s.bankPlans.some(p=>p.product===ui.bankPlanProduct&&p.direction===ui.bankPlanDirection))}>Plan einrichten</button></div>${s.bankPlans.map(p=>`<div class="list-item between"><div><h3>${p.product==='fixed'?'Festgeld':BANKS[p.product].name} · ${p.direction==='deposit'?'Sparen':'Auszahlen'}</h3><p>${cash(p.budget)} alle ${p.period} Spieltage · nächste Rate in ${duration(p.next-s.elapsed)}${p.product==='fixed'?` · ${p.days} Tage Laufzeit`:''}</p><small>${p.executions} ausgeführt · ${p.skipped} übersprungen</small></div><button class="small" ${act('cancelBankPlan',p.id)}>Beenden</button></div>`).join('')}</section>`;
}

function savingsPlansView(s,ui){
  if(s.tier<2)return '';
  return `<section class="panel mt24"><div class="between"><h3>Regelmäßig investieren ${info('plan')}</h3>${icon('refresh')}</div><div class="auto-form mt16"><div><label for="plan-stock">Wert</label><select id="plan-stock" data-setting="planStock">${Object.entries(STOCKS).filter(([id])=>C.company(s._holding||s,id)?.listed).map(([id,d])=>`<option value="${id}"${ui.planStock===id?' selected':''}>${d.name}</option>`).join('')}</select></div><div><label for="plan-budget">Rate (€)</label><input id="plan-budget" type="number" inputmode="numeric" min="10" max="1000000000000" value="${ui.amount}" data-setting="amount"></div><div><label for="plan-period">Abstand</label><select id="plan-period" data-setting="planPeriod">${[1,5,10].map(n=>`<option value="${n}"${ui.planPeriod===n?' selected':''}>${n} Spieltag${n===1?'':'e'}</option>`).join('')}</select></div></div><button class="mt16" ${act('createPlan')}${disabled(ui.amount<10||s.savingsPlans.some(p=>p.stock===ui.planStock))}>Sparplan einrichten</button>${s.savingsPlans.length?`<div class="divider"></div>${s.savingsPlans.map(p=>`<div class="list-item between"><div><h3 style="font-size:12px">${STOCKS[p.stock].name} · ${cash(p.budget)} / ${p.period} Spieltag${p.period===1?'':'e'}</h3><p>Nächste Rate in ${duration(p.next-s.elapsed)} · ${p.executions} ausgeführt · ${p.skipped} übersprungen</p></div><button class="small" ${act('cancelPlan',p.id)}>Beenden</button></div>`).join('')}`:''}</section>`;
}

function stockAnalysis(s,id){
  const p=s.stocks[id],r=p.report,next=(Math.floor(s.elapsed/(5*DAY))+1)*5*DAY;
  const multiple=p.price/r.fair;
  return `<div class="card-detail"><div class="between"><span class="eyebrow">Geschäftsbericht · Tag ${Math.floor(r.at/DAY)+1}</span>${info('stock:'+id)}</div><div class="detail-grid mt16"><p>Umsatz je Anteil / Spieljahr<strong class="number">${money(r.revenue,2)}</strong></p><p>Gewinn je Anteil / Spieljahr<strong class="number">${money(r.eps,2)}</strong></p><p>Gewinnmarge<strong class="number">${pct(r.margin,1)}</strong></p><p>Kurs-Gewinn-Verhältnis<strong class="number">${number(p.price/r.eps,1)}</strong></p><p>Modell-Ertragswert<strong class="number">${money(r.fair,2)}</strong></p><p>Kurs / Ertragswert<strong class="number">${number(multiple,2)}×</strong></p><p>Absatzpreisindex<strong class="number">${number(r.outputIndex*100,1)}</strong></p><p>Zulieferpreisindex<strong class="number">${number(r.inputIndex*100,1)}</strong></p><p>Umsatz zum Vorbericht<strong class="number">${r.growth>=0?'+':''}${pct(r.growth,1)}</strong></p><p>Dividende je Anteil / Tag<strong class="number">${money(r.dps,3)}</strong></p></div><div class="between muted" style="font-size:10px"><span>Nächster Bericht in ${duration(next-s.elapsed)}</span><span>${multiple<.9?'Unter Modellwert':multiple>1.1?'Über Modellwert':'Nahe am Modellwert'}</span></div>${s.tier>=2?`<div class="divider"></div><div class="between"><div><h3 style="font-size:12px">Dividenden ${info('stock:'+id)}</h3><p style="font-size:10px">${cash(p.reserve)} Wiederanlage-Reserve</p></div><button class="small ${p.drip?'primary':''}" ${act('drip',id)}>${p.drip?'Wiederanlage aktiv':'Wiederanlage starten'}</button></div>`:''}</div>`;
}

function propertyView(s,ui){
  return `<div class="toolbar"><span class="muted" style="font-size:11px">${cash(assets(s).properties)} Marktwert · ${cash(s.stats.rent)} Mieten netto erhalten</span></div><div class="grid2">${Object.entries(PROPERTIES).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>{const p=s.properties[id],unit=d.cost*p.index,net=(d.rent*p.occupancy-d.maintenance)*.85;return `<section class="panel"><div class="between"><div class="row gap8">${icon(d.icon)}<h3>${d.name} ${info('property:'+id)}</h3></div><span class="number" style="font-size:25px">${p.count}</span></div><div class="finance-facts mt24"><div><small>Preis je Einheit</small><strong class="number">${cash(unit)}</strong></div><div><small>Vermietung</small><strong class="number">${pct(p.occupancy,1)}</strong></div><div><small>Netto / Tag je Einheit</small><strong class="number">${cash(net)}</strong></div></div><div class="mt16">${chart(p.history.map(v=>v*d.cost),false,'Immobilienbewertung')}</div><div class="bank-actions mt16"><button ${repeat} ${act('property',id)} data-side="sell"${disabled(p.count<ui.qty)}>−${ui.qty} verkaufen</button><button ${repeat} ${act('property',id)} data-side="buy"${disabled(unit*ui.qty*1.02>s.cash)}>+${number(ui.qty)} kaufen</button><button class="all-button" ${act('propertyAll',id)} data-side="sell"${disabled(!p.count)}>Alle −</button><button class="all-button" ${act('propertyAll',id)} data-side="buy"${disabled(unit*1.02>s.cash||p.count>=100000)}>Alle +</button></div><div class="mt8 muted" style="font-size:10px">Kauf gesamt inkl. Kosten: ${cash(unit*ui.qty*1.02)}</div></section>`;}).join('')}</div>`;
}

function hedgesView(s,ui){
  const id=RESOURCES[ui.optionResource]?.tier<=s.tier?ui.optionResource:'wood',q=optionQuote(s,id,ui.optionType,ui.qty,ui.optionDays);
  return `<div class="toolbar"><div class="row"><span class="muted" style="font-size:11px">Markterlöse absichern ${info('options')}</span></div></div><section class="panel"><div class="auto-form"><div><label for="option-resource">Referenzware</label><select id="option-resource" data-setting="optionResource">${Object.entries(RESOURCES).filter(([,d])=>d.tier<=s.tier).map(([r,d])=>`<option value="${r}"${r===id?' selected':''}>${d.name}</option>`).join('')}</select></div><div><label for="option-type">Schutz</label><select id="option-type" data-setting="optionType"><option value="put"${ui.optionType==='put'?' selected':''}>Put · gegen fallende Preise</option><option value="call"${ui.optionType==='call'?' selected':''}>Call · gegen steigende Preise</option></select></div><div><label for="option-days">Laufzeit</label><select id="option-days" data-setting="optionDays">${[1,3,7].map(d=>`<option value="${d}"${ui.optionDays===d?' selected':''}>${d} Spieltag${d===1?'':'e'} · ${duration(d*DAY)} echt</option>`).join('')}</select></div></div><div class="finance-facts mt24"><div><small>Vereinbarter Preis ${info('optionModel')}</small><strong class="number">${money(q.strike,2)}</strong></div><div><small>Menge</small><strong class="number">${ui.qty}</strong></div><div><small>Prämie = maximaler Verlust</small><strong class="number">${money(q.premium,2)}</strong></div></div><button class="mt24" ${act('buyOption')}${disabled(q.premium>s.cash||s.options.length>=20)}>Absicherung kaufen · ${money(q.premium,2)}</button></section>${s.options.length?`<div class="subheading">Laufende Absicherungen</div><div class="grid2">${s.options.map(o=>{const value=optionPrice(referencePrice(s,o.resource),o.strike,Math.max(0,(o.end-s.elapsed)/DAY),o.volatility,o.type)*o.quantity;return `<section class="panel"><div class="between"><h3>${o.type==='put'?'Put':'Call'} · ${RESOURCES[o.resource].name} ${info('options')}</h3><span class="number">${o.quantity}</span></div><div class="detail-grid mt16"><p>Basispreis<strong>${money(o.strike,2)}</strong></p><p>Geglätteter Marktpreis jetzt<strong>${money(referencePrice(s,o.resource),2)}</strong></p><p>Optionswert vor Verkaufskosten<strong>${money(value,2)}</strong></p><p>Restlaufzeit echt<strong>${duration(o.end-s.elapsed)}</strong></p></div><button class="small" ${act('sellOption',o.id)}>Vorzeitig verkaufen</button></section>`;}).join('')}</div>`:''}`;
}

function plannerView(s,ui={}){
  const actual=ui.planMode!=='planned',rows=actual?currentSupplyPlan(s):supplyPlan(s);
  return `<div class="toolbar planning-toolbar"><div class="between"><h3>Deine Kette, in Zahlen. ${info('planner')}</h3></div><select data-setting="planMode" aria-label="Mengenbasis"><option value="actual"${actual?' selected':''}>Ist · aktuelle Produktion</option><option value="planned"${!actual?' selected':''}>Soll · volle Auslastung</option></select></div><p class="analysis-note">${actual?'Momentane Mengen mit aktiven Betrieben, aktuellen Boni und Engpässen.':'Geplante Mengen aller aktiven Betriebe mit aktuellen Boni bei voller Auslastung.'} Alle Mengen pro Spielstunde; Aktualisierung alle 0,5 Sekunden.</p><div class="plan-table"><div class="plan-row plan-heading"><span>Ware</span><span>Produktion / h</span><span>Verbrauch / h</span><span>Saldo / h</span><span>Reichweite</span><span></span></div>${rows.map(r=>`<div class="plan-row" data-key="plan:${r.id}"><span class="row gap8">${icon(RESOURCES[r.id].icon)}${RESOURCES[r.id].name} ${info('resource:'+r.id)}</span><span class="number" data-label="Produktion / h">${number(r.output,2)}</span><span class="number" data-label="Verbrauch / h">${number(r.input,2)}</span><span class="number ${r.net<0?'negative':''}" data-label="Saldo / h">${r.net<0?'−':'+'}${number(Math.abs(r.net),2)}</span><span class="number" data-label="Reichweite">${Number.isFinite(r.hours)?number(r.hours,1)+' h':'∞'}</span><button class="small" ${act('goResource',r.id)}>Markt</button></div>`).join('')}</div>`;
}

export function finance(s,ui) {
  normalizeUI(ui,s);
  if(s.tier<1)return empty('Noch unentdeckt','Dein Unternehmen wird dir diesen Bereich zur passenden Zeit eröffnen.','compass');
  const tabs=[['bank','Bank'],['stocks','Börse'],['bonds','Anleihen'],['ventures','Beteiligungen'],...(s.tier>=2?[['properties','Sachwerte']]:[]),...(s.tier>=3?[['hedges','Absicherung']]:[])];
  const holdings=s.bonds.length||s.ventures.length?`<div class="subheading">Gebundenes Kapital</div><div class="panel">${s.bonds.map(b=>`<div class="list-item between"><div><h3 style="font-size:13px">${b.type==='fixed'?'Festgeld':BONDS[b.type].name} · ${cash(b.principal)}</h3><p>Fällig in ${duration(b.end-s.elapsed)} · ${pct(b.rate,2)} / Spieltag</p><small class="number">${preciseCash(b.principal*(Math.pow(1+b.rate,Math.max(0,Math.min(b.end,s.elapsed)-b.start)/DAY)-1)*.85)} aufgelaufene Nettozinsen${BONDS[b.type]?.risk?' vor Ausfallrisiko':''} · Auszahlung bei Fälligkeit</small></div>${b.type==='fixed'?`<button class="small" ${act('redeemFixed',b.id)}>Auflösen</button>`:icon('clock')}</div>`).join('')}${s.ventures.map(v=>`<div class="list-item between"><div><h3 style="font-size:13px">${VENTURES[v.type].name} · ${cash(v.principal)}</h3><p>Ergebnis in ${duration(v.end-s.elapsed)}</p></div>${icon('compass')}</div>`).join('')}</div>`:'';
  return `${head('Zeit ist Kapital','Geld in Bewegung.','Lege Rücklagen an. Finanziere Wachstum. Trage bewusst Risiken.')}<div class="sticky-controls finance-control-stack"><div class="toolbar"><div class="segmented finance-tabs" style="--tab-columns:${tabs.length===4?2:3}">${tabs.map(([id,n])=>`<button ${act('financeTab',id)} class="${ui.financeTab===id?'active':''}">${n}</button>`).join('')}</div><span class="muted" style="font-size:11px">${preciseCash(s.cash)} verfügbar</span></div>${!['stocks','properties','hedges'].includes(ui.financeTab)?amountControl(ui):quantity(ui)}</div>${ui.financeTab==='bank'?banks(s,ui)+bankPlansView(s,ui)+treasuryView(s,ui):ui.financeTab==='stocks'?stocks(s,ui)+savingsPlansView(s,ui):ui.financeTab==='bonds'?bonds(s,ui):ui.financeTab==='properties'?propertyView(s,ui):ui.financeTab==='hedges'?hedgesView(s,ui):ventures(s,ui)}${holdings}`;
}

export function researchView(s,ui) {
  return `${head('Wissen verändert alles','Besser statt größer.','Forschungsinstitute erzeugen Punkte. Verbesserungen wirken dauerhaft.',`<div class="align-right"><div class="eyebrow">Forschung</div><div class="number" style="font-size:28px">${number(s.points,1)} <small>FP</small></div></div>`)}${!researchRate(s)?`<div class="notice"><strong>Ein Ort für neue Ideen.</strong> Baue dein erstes Forschungsinstitut unter Betriebe → Infrastruktur. Es erzeugt einen Forschungspunkt pro Spielstunde und kostet 10 €/h.<div class="mt16"><button class="small" ${act('goLab')}>Zur Infrastruktur ${icon('arrow')}</button></div></div>`:''}<div class="grid3">${Object.entries(RESEARCH).filter(([,r])=>r.tier<=s.tier).map(([id,r])=>{const level=s.research[id],cost=researchCost(s,id),max=level>=r.max;return `<section class="panel research-card"><div class="between">${icon(r.icon)}<span class="eyebrow">Stufe ${level}</span></div><h3>${r.name} ${info('research:'+id)}</h3><div class="level-dots">${Array.from({length:r.max},(_,i)=>`<i class="${i<level?'filled':''}"></i>`).join('')}</div><div class="research-cost"><span class="muted">${max?'Abgeschlossen':`${cost.points} FP · ${cash(cost.cash)}`}</span><button class="small ${!max&&s.points>=cost.points&&s.cash>=cost.cash?'primary':''}" ${act('research',id)}${disabled(max||s.points<cost.points||s.cash<cost.cash)}>${max?icon('check'):'Forschen'}</button></div></section>`;}).join('')}</div>`;
}

export function contracts(s) {
  const card=(c,active)=>`<article class="contract-card"><div class="between"><div class="row gap8">${icon(RESOURCES[c.resource].icon)}<h3>${RESOURCES[c.resource].name} ${info('contracts')}</h3></div><span class="eyebrow">${active?'Laufend':`+${number((c.premium-1)*100)} % Prämie`}</span></div><div class="contract-quantity number">${c.quantity} <small>Einheiten</small></div><div class="contract-reward number">${cash(c.reward)}</div><p class="mt8">${active?`Noch ${duration(c.end-s.elapsed)} echte Zeit`:`Lieferfrist: ${duration(c.duration)} echte Zeit`}</p>${active?`${meter('Bereit zur Lieferung',s.inventory[c.resource],c.quantity)}<div class="row"><button class="wfull primary" ${act('fulfill',c.id)}${disabled(s.inventory[c.resource]+1e-7<c.quantity)}>Liefern</button><button class="icon-button" ${act('abandon',c.id)} aria-label="Vertrag aufgeben">${icon('close')}</button></div>`:`<button class="wfull mt24" ${act('accept',c.id)}${disabled(s.contracts.length>=3)}>Auftrag annehmen</button>`}</article>`;
  return `${head('Vertrauen wird belohnt','Versprechen mit Wert.','Liefere Waren zum vereinbarten Preis. Erhalte Prämien, Reputation und Forschungspunkte.')}<div class="subheading" style="margin-top:0">Laufende Verträge <span class="muted">${s.contracts.length} / 3</span></div>${s.contracts.length?`<div class="grid3">${s.contracts.map(c=>card(c,true)).join('')}</div>`:`<div class="panel flat">${empty('Noch kein Versprechen.','Nimm einen Auftrag an, den deine Produktionskette rechtzeitig erfüllen kann.','file')}</div>`}<div class="subheading">Neue Gelegenheiten <span class="muted" style="font-size:10px">Neue Angebote alle 6 echten Minuten</span></div><div class="grid3">${s.board.map(c=>card(c,false)).join('')}</div><p class="fine-print">Du lieferst die gesamte Menge per Schaltfläche. Achte auf automatische Verkäufe: Halte für Aufträge genug Ware zurück. Erfüllung: +2 Reputation und Forschungspunkte. Fristablauf oder Aufgabe: −3 Reputation, keine Geldstrafe. Bei Prämien ist der Marktpreis zum Zeitpunkt des Angebots maßgeblich.</p>`;
}

export function journal(s) {
  return `${head('Deine Geschichte','Entscheidungen hinterlassen Spuren.','Ereignisse, Entdeckungen und die letzten 100 Einträge deines Unternehmens.')}<div class="timeline">${s.journal.map(j=>`<div class="timeline-item ${esc(j.type)}"><small>TAG ${Math.floor(j.at/DAY)+1} · ${String(Math.floor(j.at%DAY/HOUR)).padStart(2,'0')}:00</small><p class="mt8">${esc(j.text)}</p></div>`).join('')}</div>`;
}

function programmeSummary(s){
  if(!s.campaign.unlocked)return '';
  const active=s.campaign.active,chapter=active?PROGRAMMES.find(p=>p.id===active.chapter):programmeOffer(s);
  return `<section class="panel"><div class="panel-header"><h3>Deine Holding</h3>${info('programmes')}</div><p>${active?`${esc(chapter.name)} · noch ${duration(active.end-s.campaign.age)} echte Zeit`:chapter?'Ein neues Holdingprogramm ist verfügbar.':'Dein Unternehmen wächst auf den nächsten langfristigen Schritt zu.'}</p><button class="small mt16" ${act('tab','programmes')}>Holdingprogramme ${icon('arrow')}</button></section>`;
}

export function programmes(s){
  if(!s.campaign.unlocked)return empty('Noch unentdeckt','Dein Unternehmen wird dir diesen Bereich zur passenden Zeit eröffnen.','compass');
  const c=s.campaign,active=c.active,chapter=active?PROGRAMMES.find(p=>p.id===active.chapter):programmeOffer(s);
  const bonuses=`<section class="panel"><div class="panel-header"><h3>Bleibende Spezialisierung</h3>${info('programmeBonuses')}</div>${Object.entries(PROGRAMME_CHOICES).map(([id,d])=>`<div class="balance-line"><span>${icon(d.icon)} ${d.name}</span><strong class="number">+${number(c.bonuses[id])} %</strong></div>`).join('')}</section>`;
  let project='';
  if(active){
    project=`<section class="panel"><div class="panel-header"><h3>${chapter.name}</h3>${info('programmes')}</div><p>${chapter.brief}</p><div class="divider"></div>${meter('Umsetzung',Math.min(100,100*(c.age-active.start)/chapter.duration),100,' %')}<div class="balance-line"><span>Verbleibende echte Zeit</span><strong class="number">${duration(active.end-c.age)}</strong></div><div class="balance-line"><span>Gewählter Schwerpunkt</span><strong>${PROGRAMME_CHOICES[active.choice].name} +${chapter.bonus[active.choice]} %</strong></div><p class="fine-print">Die Investition ist bezahlt. Das Programm läuft auch offline weiter.</p></section>`;
  }else if(chapter){
    const affordable=s.cash>=chapter.cash&&s.points>=chapter.points&&Object.entries(chapter.materials).every(([id,q])=>s.inventory[id]+1e-7>=q);
    const missing=[];
    if(s.cash<chapter.cash)missing.push(`${cash(Math.ceil(chapter.cash-s.cash))} Betriebskapital`);
    if(s.points<chapter.points)missing.push(`${number(Math.ceil(chapter.points-s.points))} Forschungspunkte`);
    if(Object.entries(chapter.materials).some(([id,q])=>s.inventory[id]+1e-7<q))missing.push('Materialvorräte');
    project=`<section class="panel"><div class="panel-header"><h3>${chapter.name}</h3>${info('programmes')}</div><p>${chapter.brief}</p><div class="divider"></div><div class="balance-line"><span>Kapital verfügbar / benötigt</span><strong class="number ${s.cash<chapter.cash?'negative':''}">${cash(s.cash)} / ${cash(chapter.cash)}</strong></div><div class="balance-line"><span>Forschungspunkte</span><strong class="number">${number(s.points)} / ${number(chapter.points)}</strong></div>${Object.entries(chapter.materials).map(([id,q])=>`<div class="balance-line"><span>${RESOURCES[id].name} ${info('resource:'+id)}</span><span class="number ${s.inventory[id]+1e-7<q?'negative':''}">${number(s.inventory[id],1)} / ${number(q)}</span></div>`).join('')}<div class="balance-line"><span>Laufzeit in echter Zeit</span><strong>${duration(chapter.duration)}</strong></div><div class="row wrap mt16"><button class="small" ${act('programmeReserve')}>Material bevorraten</button>${info('programmeReserve')}</div><div class="divider"></div><div class="grid3">${Object.entries(PROGRAMME_CHOICES).map(([id,d])=>`<div><h3>${icon(d.icon)} ${d.name} ${info('programmeBonuses',d.name+' erklären')}</h3><div class="secondary-value number mt16">+${chapter.bonus[id]} %</div><button class="small mt16" ${act('startProgramme',id)}${disabled(!affordable)}>Diesen Schwerpunkt wählen</button></div>`).join('')}</div>${!affordable?`<p class="notice mt16" role="status">Zum Start fehlen: ${missing.join(', ')}.</p>`:''}</section>`;
  }else project=`<section class="panel"><h3>${c.completed.length===PROGRAMMES.length?'Eine Holding mit Geschichte.':'Deine nächste Gelegenheit wächst.'}</h3><p class="mt16">${c.completed.length===PROGRAMMES.length?'Alle Holdingprogramme abgeschlossen. Deine dauerhaften Schwerpunkte tragen dein Unternehmen und jede künftige Neugründung.':'Es ist gerade kein neues Programm verfügbar. Entwickle dein Unternehmen und entdecke den nächsten Horizont.'}</p></section>`;
  return `${head('Was bleibt und weiterwächst','Deine eigene Handschrift.')}<div class="grid2">${project}${bonuses}</div>${c.completed.length?`<div class="subheading">Abgeschlossene Programme</div><div class="panel">${c.completed.map(item=>{const p=PROGRAMMES.find(d=>d.id===item.chapter);return `<div class="list-item between wrap"><span>${p.name}</span><strong>${PROGRAMME_CHOICES[item.choice].name} +${p.bonus[item.choice]} %</strong></div>`;}).join('')}</div>`:''}`;
}

export function statistics(s) {
  const a=assets(s), earned=s.achievements.length;
  return `${head('Was bleibt','Eine Bilanz deiner Entscheidungen.')}<div class="grid2"><section class="panel"><div class="panel-header"><h3>Vermögensbilanz</h3>${icon('file')}</div>${[['Liquidität',a.cash],['Warenlager',a.inventory],['Anlagevermögen (Buchwert)',a.buildings],...(s.tier>=1?[['Bankguthaben',a.banks],['Wertpapiere inkl. Depotreserve',a.securities],['Anleihen & Festgeld',a.bonds],['Beteiligungen (Einstand)',a.ventures],['Verbindlichkeiten',-a.debt]]:[]),...(s.tier>=2?[['Anlageimmobilien',a.properties]]:[]),...(s.tier>=3?[['Absicherungen (Modellwert)',a.options]]:[]),...(s.group?[["Tochteranteile (Buchwert)",a.subsidiaries],["Firmenforderungen",a.receivables],["Verkäuferfinanzierung",-a.payables],["Konzern-Eigenkapital",a.groupEquity],["Privatvermögen",a.wallet]]:a.receivables?[["Firmenforderungen",a.receivables]]:[]),['Nettovermögen (dein Anteil)',a.total]].map(([name,n])=>`<div class="balance-line"><span>${name}</span><span class="number">${cash(n)}</span></div>`).join('')}</section><section class="panel"><div class="panel-header"><h3>Seit der Gründung</h3>${icon('chart')}</div>${[['Gesamter Warenumsatz',s.stats.revenue],['Laufende Ausgaben',s.stats.expenses],...(s.tier>=1?[['Nettozinsen',s.stats.interest],['Nettodividenden',s.stats.dividends]]:[]),...(s.tier>=2?[['Nettomieten',s.stats.rent]]:[]),...(s.tier>=3?[['Absicherungen: realisiertes Ergebnis',s.stats.optionPnl]]:[]),['Gezahlte / gestundete Steuern',s.stats.taxes],['Höchstes Nettovermögen',s.stats.peak]].map(([name,n])=>`<div class="balance-line"><span>${name}</span><span class="number">${cash(n)}</span></div>`).join('')}<div class="balance-line"><span>Erfüllte Verträge</span><span class="number">${s.stats.contracts}</span></div><div class="balance-line"><span>Simulierte echte Zeit</span><span class="number">${duration(s.elapsed)}</span></div></section></div><div class="subheading">Meilensteine <span class="muted">${earned} entdeckt</span></div><div class="grid3">${ACHIEVEMENTS.filter(a=>s.achievements.includes(a.id)||['firstBuild','firstTrade','ten','contract'].includes(a.id)||(s.tier>=1&&['chain','research','invest'].includes(a.id))||(s.tier>=2&&a.id==='diverse')).map(a=>`<div class="achievement ${s.achievements.includes(a.id)?'done':''}">${icon(s.achievements.includes(a.id)?'trophy':'compass')}<div><h3>${a.name}</h3><p>${a.description}</p><small>${s.achievements.includes(a.id)?'Erreicht':`Prämie ${cash(a.reward)}`}</small></div></div>`).join('')}</div>`;
}

export function more(s) {
  const links=[...(s.tier>=1?[['research','flask','Forschung','Ideen werden zu Vorsprung']]:[]),...(s.campaign.unlocked?[['programmes','orbit','Holdingprogramme','Ein Schwerpunkt, der bleibt']]:[]),['contracts','file','Lieferaufträge','Zuverlässigkeit zahlt sich aus'],['analysis','chart','Analyse & Bilanz','Verläufe, Kennzahlen und Meilensteine'],['legacy','orbit','Vermächtnis','Punkte, Boni und nächste Ziele'],['journal','clock','Chronik','Deine Unternehmensgeschichte'],['saves','save','Spielstände','Speichern, laden, exportieren'],['guide','book','Spielanleitung','Verstehe dein System'],['install','download','iPhone-Installation','Dein Spiel auf dem Home-Bildschirm'],['menu','menu','Hauptmenü','Ein Moment zum Durchatmen']];
  return `${head('Dein Unternehmen','Es gibt mehr zu entdecken.')}<div class="more-grid">${links.map(([id,glyph,name,sub])=>`<button class="more-link" ${act(['saves','guide','install','menu'].includes(id)?id:'tab',id)}>${icon(glyph)}<span><strong>${name}</strong><small>${sub}</small></span></button>`).join('')}</div><section class="panel flat mt24"><div class="between"><div><h3>${esc(s.name)}</h3><p class="fine-print">Dein Name für diese Wirtschaft.</p></div><button class="small" ${act('rename')}>Umbenennen</button></div></section>`;
}

export function savesView(s,ui,saves) {
  return `${head('Ein sicherer Stand','Deine Geschichte gehört dir.','Drei manuelle Spielstände, automatische Sicherung und Dateiexport.')}<div class="grid2">${saves.map(slot=>`<section class="save-slot"><div class="between"><h3>${slot.slot==='auto'?'Automatischer Spielstand':`Spielstand ${slot.slot.slice(-1)}`}</h3>${icon('save')}</div>${slot.error?`<p>Beschädigt: ${esc(slot.error)}</p>`:slot.empty?'<p>Noch kein Spielstand.</p>':`<p>${esc(slot.name)} · ${TIERS[slot.tier].name}<br>${cash(slot.cash)} · Tag ${Math.floor(slot.elapsed/DAY)+1}<br>${new Date(slot.saved).toLocaleString('de-DE')}${slot.recovered?' · Sicherungskopie':''}</p>`}<div class="row">${slot.slot!=='auto'?`<button ${act('saveSlot',slot.slot)}${disabled(!s)}>Speichern</button>`:''}<button ${act('loadSlot',slot.slot)}${disabled(slot.empty||slot.error)}>Laden</button>${slot.slot!=='auto'&&!slot.empty?`<button ${act('deleteSlot',slot.slot)} aria-label="Spielstand löschen" class="icon-button">${icon('close')}</button>`:''}</div></section>`).join('')}</div><section class="panel mt24"><div class="between wrap"><div><h3>Eine Kopie für alle Fälle.</h3><p class="fine-print">Browserdaten können gelöscht werden. Ein Export bleibt deine unabhängige Sicherung.</p></div><div class="row wrap"><button ${act('export')}${disabled(!s)}>${icon('download')} Exportieren</button><button ${act('import')}>${icon('upload')} Importieren</button></div></div></section>${ui.saveError?`<div class="notice mt24"><strong>Lokaler Speicher eingeschränkt.</strong> ${esc(ui.saveError)} Exportiere deinen Spielstand, bevor du die App schließt.</div>`:''}<p class="fine-print">Automatisch alle 15 Sekunden, nach Aktionen und beim Verlassen. Jeder Speicherplatz hält zusätzlich seine letzte gültige Sicherungskopie vor. Manuelle Spielstände sind Momentaufnahmen; beim Laden wird die seit ihrer Sicherung verstrichene Zeit simuliert. Safari und die Home-Bildschirm-App können getrennte Speicher verwenden: Übertrage deinen Spielstand bei Bedarf per Export und Import.</p>`;
}

export function guide(s){return `${head('Deine Wirtschaft','Vom Betrieb zur Holding.')}<div class="guide"><section class="panel"><h3>Vier Ketten, zehn Betriebe</h3><p>Holz → Bretter → Möbel. Getreide → Brot. Erz → Eisen → Werkzeuge. Stein → Ziegel. Vorprodukte können aus eigener Produktion, Markt oder Konzernverträgen stammen. Werkzeuge benötigen zusätzlich Bretter.</p></section><section class="panel mt16"><h3>Ein tragfähiger Anfang</h3><p>Baue einen Holzfäller und verkaufe Überschüsse automatisch, beispielsweise über 20 Holz. Personal, Energie, Transport und Lager begrenzen die Produktion. Ein echter Tag hat 60 Spieltage; ein Spieltag dauert 24 echte Minuten. Gedrückthalten von 100× beschleunigt alle Systeme.</p></section><section class="panel mt16"><h3>Unternehmen führen</h3><p>Ab 2.000 € Konzernvermögen kannst du Töchter gründen. Weise ihnen Kapital und Assets zu. Der Unternehmenswähler legt fest, welche Kasse und Betriebe du bedienst. Holding und Töchter haben getrennte Schulden. Interne Transaktionen erhöhen das Konzernvermögen nicht.</p><p>CEOs folgen Mandat, Reserve und Investitionsbudget. Ihre Entscheidungen stehen an der Firma. Ausschüttungen erfolgen aus positivem Ergebnis und verfügbarer Liquidität. Firmen arbeiten auch offline weiter; Eingriffe sind jederzeit möglich.</p></section><section class="panel mt16"><h3>Eigentum und Finanzierung</h3><p>Börsenaktien haben endliche Stückzahlen und gehören wirtschaftenden Firmen mit Anlagen, Vorräten und Schulden. Private Anteile werden verhandelt. Mehr als 50 % der Stimmrechte erlauben die Führung, 100 % den freien Assettransfer. Dividenden erhalten alle Eigentümer anteilig.</p><p>GmbH und AG trennen die Finanzierung. Eine AG kann an die Börse gehen und neue Aktien ausgeben. Kapitalerhöhungen finanzieren die Firma und verwässern bestehende Anteile. Eigene und fremde Firmen können Kredite aus der Holding erhalten; Zinszahlungen hängen von ihrer Zahlungsfähigkeit ab.</p></section><section class="panel mt16"><h3>Absicherung verstehen</h3><p>Ein Put zahlt bei fallendem, ein Call bei steigendem geglättetem Marktpreis. Eigene Verkäufe beeinflussen diesen Marktpreis mit Verzögerung. Mehr Produktion ohne Absatz senkt keinen Preis. Laufzeit, Prämie, Auszahlung und das zugrunde liegende Geschäft müssen gemeinsam betrachtet werden. Ein wertlos verfallener Put kann mit hohen Verkaufserlösen zusammenfallen.</p></section><section class="panel mt16"><h3>Speichern und Abwesenheit</h3><p>Automatische Sicherung alle 15 Sekunden. Exportiere zusätzlich unabhängige Sicherungen. Bis zu sieben echte Tage werden mit denselben Regeln nachgerechnet. Markt, Verträge, Kreditraten, CEOs und Dividenden laufen weiter. Neue App-Versionen werden vollständig zwischengespeichert; ein Update sichert zuvor deinen Stand.</p></section></div>`;}

function seriesPlot(samples,key,title,unit='€'){
  const points=samples.filter(h=>Number.isFinite(h[key]));
  if(!points.length)return '';
  const values=points.map(h=>h[key]),min=Math.min(...values),max=Math.max(...values);
  const format=value=>unit==='%'?pct(value,1):unit==='€'?preciseCash(value):number(value,1)+(unit?' '+unit:'');
  const plot=chart(values,true,title);
  const targets=points.map((h,i)=>`<rect class="chart-target" data-chart-value="${esc(gameTime({elapsed:h.at})+': '+format(h[key]))}" x="${i*600/points.length}" y="0" width="${600/points.length}" height="150"><title>${esc(gameTime({elapsed:h.at}))}: ${esc(format(h[key]))}</title></rect>`).join('');
  return `<figure class="panel analysis-plot"><figcaption><span>${title}</span><strong class="number">${format(values.at(-1))}</strong></figcaption><div class="plot-scale"><span>${format(max)}</span><span>${format(min)}</span></div>${plot.replace('</svg>',targets+'</svg>')}<div class="chart-caption"><span>${gameTime({elapsed:points[0].at})}</span><span>${points.length===1?'Live':gameTime({elapsed:points.at(-1).at})}</span></div><output class="chart-readout" data-preserve-text aria-live="polite"></output></figure>`;
}

function barPlot(rows,title,unit=''){
  const max=Math.max(1,...rows.map(row=>Math.abs(row.value)));
  return `<section class="panel analysis-bars"><h3>${title}</h3>${rows.length?rows.map(row=>`<div class="analysis-bar"><div class="between"><span>${esc(row.name)}</span><strong class="number">${row.value<0?'−':''}${number(Math.abs(row.value),1)}${unit}</strong></div><div class="meter-track"><div class="meter-fill ${row.value<0?'deficit':''}" style="width:${Math.abs(row.value)/max*100}%"></div></div></div>`).join(''):'<p>Noch keine aktiven Werte.</p>'}</section>`;
}

export function analysis(s,ui){
  normalizeUI(ui,s);
  const tabs=[['company','Unternehmen'],['income','Geldflüsse'],['production','Produktion'],['markets','Märkte'],['balance','Bilanz']];
  const snapshot=historySnapshot(s),samples=[...s.stats.history.filter(h=>h.at>=s.elapsed-ui.analysisHours*HOUR&&h.at<s.elapsed),snapshot];
  const controls=`<div class="toolbar sticky-controls analysis-controls"><div class="segmented">${tabs.map(([id,name])=>`<button ${act('analysisTab',id)} class="${ui.analysisTab===id?'active':''}">${name}</button>`).join('')}</div><select data-setting="analysisHours" aria-label="Analysezeitraum">${[24,48,96].map(n=>`<option value="${n}"${n===ui.analysisHours?' selected':''}>${n} Spielstunden</option>`).join('')}</select></div>`;
  let content='';
  if(ui.analysisTab==='company'){
    content=`<div class="analysis-grid">${[['wealth','Nettovermögen'],['cash','Betriebskasse'],['inventory','Warenwert'],...(s.tier>=1?[['banks','Bankguthaben'],['securities','Depotwert'],['debt','Verbindlichkeiten']]:[])].map(([key,title])=>seriesPlot(samples,key,title)).join('')}</div>`;
  }else if(ui.analysisTab==='income'){
    content=`<p class="analysis-note">Laufende Buchungen alle 0,5 Sekunden. Stundenwerte zeigen die aktuelle Stunde bisher; Zinsen, Dividenden, Mieten und Steuern sind seit der Gründung kumuliert.</p><div class="analysis-grid">${[['profit','Operativer Überschuss / Stunde'],['revenue','Warenumsatz / Stunde'],['costs','Einkauf & laufende Kosten / Stunde'],...(s.tier>=1?[['interest','Nettozinsen'],['dividends','Nettodividenden']]:[]),...(s.tier>=2?[['rent','Nettomieten']]:[]),['taxes','Steuern']].map(([key,title])=>seriesPlot(samples,key,title)).join('')}</div>`;
  }else if(ui.analysisTab==='production'){
    const c=capacity(s),rates=Object.entries(BUILDINGS).filter(([id])=>s.buildings[id].count).map(([id,b])=>({id,b,rate:buildingRate(s,id)}));
    content=`<div class="analysis-grid">${seriesPlot(samples,'produced','Produziert gesamt','Einheiten')}${seriesPlot(samples,'points','Forschungspunkte','FP')}${seriesPlot(samples,'staffing','Personalversorgung','%')}${seriesPlot(samples,'power','Energieversorgung','%')}${seriesPlot(samples,'logistics','Transportversorgung','%')}</div><div class="grid2 mt16">${barPlot(rates.map(({b,rate})=>({name:b.name,value:rate.utilization*100})),'Momentane Auslastung',' %')}${barPlot(supplyPlan(s).filter(r=>r.input||r.output).map(r=>({name:RESOURCES[r.id].name,value:r.net})),'Geplante Warenbilanz',' / h')}</div><details class="panel mt16" data-preserve-open><summary>Betriebsdetails · ${rates.length} Typen</summary><div class="analysis-table"><table><thead><tr><th>Betrieb</th><th>Aktiv</th><th>Auslastung</th><th>Ausstoß / h</th><th>Marge / h</th></tr></thead><tbody>${rates.map(({id,b,rate})=>`<tr><th>${b.name} ${info('building:'+id)}</th><td>${number(s.buildings[id].active)}</td><td>${pct(rate.utilization,1)}</td><td>${number(Object.values(b.output).reduce((n,q)=>n+q*rate.units,0),1)}</td><td>${cash(rate.margin*s.buildings[id].active*rate.utilization)}</td></tr>`).join('')}</tbody></table></div><p class="analysis-note">Marge zum Mittelkurs vor Gebühren, Umweltkosten und Steuern. ${number(c.pollution,1)} Umweltbelastung · ${cash(c.ecoCost)} Umweltkosten / h.</p></details>`;
  }else if(ui.analysisTab==='markets'){
    const id=ui.analysisResource,r=RESOURCES[id],stock=s.stocks[ui.analysisStock],d=STOCKS[ui.analysisStock];
    const marketSamples=s.market[id].history.slice(-Math.min(48,ui.analysisHours)).map((value,index,array)=>({at:Math.max(0,Math.floor(s.elapsed/HOUR)*HOUR-(array.length-1-index)*HOUR),price:value}));
    marketSamples.push({at:s.elapsed,price:price(s,id)});
    content=`<div class="auto-form market-selectors"><div><label for="analysis-resource">Ware</label><select id="analysis-resource" data-setting="analysisResource">${Object.entries(RESOURCES).filter(([,r])=>r.tier<=s.tier).map(([key,r])=>`<option value="${key}"${key===id?' selected':''}>${r.name}</option>`).join('')}</select></div>${s.tier>=1?`<div><label for="analysis-stock">Aktie</label><select id="analysis-stock" data-setting="analysisStock">${Object.entries(STOCKS).map(([key,d])=>`<option value="${key}"${key===ui.analysisStock?' selected':''}>${d.name}</option>`).join('')}</select></div>`:''}</div><div class="analysis-grid">${seriesPlot(marketSamples,'price',r.name+' · Mittelkurs')}${s.tier>=1?seriesPlot([...stock.history.map((value,index,array)=>({at:Math.max(0,Math.floor(s.elapsed/HOUR)*HOUR-(array.length-1-index)*HOUR),price:value})),{at:s.elapsed,price:stock.price}].slice(-ui.analysisHours-1),'price',d.name+' · Kurs'):''}</div><section class="panel mt16"><div class="between"><h3>${r.name} ${info('resource:'+id)}</h3><strong class="number">${number(s.inventory[id],2)} im Lager</strong></div><div class="detail-grid mt8"><p>Kauf ${number(ui.qty)}<strong>${preciseCash(quote(s,id,ui.qty,'buy').total)}</strong></p><p>Verkauf ${number(ui.qty)}<strong>${preciseCash(quote(s,id,ui.qty,'sell').total)}</strong></p></div></section>${s.tier>=1?`<section class="panel mt16"><h3>${d.full} ${info('stock:'+ui.analysisStock)}</h3>${stockAnalysis(s,ui.analysisStock)}</section>`:''}<div class="grid2 mt16">${barPlot(Object.entries(RESOURCES).filter(([id,r])=>r.tier<=s.tier&&s.inventory[id]>0).map(([id,r])=>({name:r.name,value:s.inventory[id]*price(s,id)*.98})),'Lager nach Marktwert',' €')}${s.tier>=1?barPlot(Object.entries(STOCKS).filter(([id])=>s.stocks[id].quantity).map(([id,d])=>({name:d.name,value:s.stocks[id].quantity*s.stocks[id].price*.995+s.stocks[id].reserve})),'Depot nach Marktwert',' €'):''}</div>`;
  }else content=statistics(s);
  return `${head('Analyse','Deine Wirtschaft im Detail.','Verläufe, Geldflüsse, Produktionsleistung und Bewertungen.')}${controls}${content}<p class="analysis-note">Stündliche Stichproben und aktueller Live-Wert. Neue Kennzahlen werden ab diesem Update aufgezeichnet; alte Verlaufspunkte bleiben erhalten. Kursverläufe umfassen höchstens 48 Spielstunden. Tippe oder zeige auf den Verlauf für einzelne Werte.</p>`;
}

export function legacyView(s){
  const progress=legacyProgress(s),targets=Array.from({length:8},(_,i)=>progress.pending+i+1);
  return `${head('Vermächtnis','Was du weitergibst.','Dauerhafte Punkte für deine nächste Holding.')}<div class="grid2"><section class="panel"><div class="panel-header"><h3>Erreicht & dauerhaft aktiv</h3>${icon('orbit')}</div><div class="legacy-points number">${number(progress.earned)} <small>Punkte</small></div><div class="balance-line"><span>Produktionsbonus</span><strong>+${pct(progress.production)}</strong></div><div class="balance-line"><span>Forschungsbonus</span><strong>+${pct(progress.research)}</strong></div><div class="balance-line"><span>Zusätzliches Startkapital</span><strong>${cash(progress.startCash)}</strong></div><div class="balance-line"><span>Holding-Neugründungen</span><strong>${number(s.prestigeCount)}</strong></div></section><section class="panel"><div class="panel-header"><h3>Bei deiner nächsten Neugründung</h3>${info('legacy')}</div><div class="legacy-points number">+${number(progress.pending)} <small>Punkte verfügbar</small></div><p>Du behältst deine ${number(progress.earned)} Punkte und erhältst ${number(progress.pending)} weitere. Danach: ${number(progress.earned+progress.pending)} Punkte.</p>${meter('Höchstvermögen bis zur nächsten Punktestufe',s.stats.peak,progress.threshold,' €')}<p class="analysis-note">Nächster zusätzlicher Punkt bei ${cash(progress.threshold)} · noch ${cash(progress.remaining)}.</p><button class="wfull mt8" ${act('prestige')}${disabled(!progress.pending)}>Neue Holding gründen · +${number(progress.pending)}</button></section></div><section class="panel mt16"><h3>So entstehen Vermächtnispunkte</h3><p class="mt8">Ab 100 Millionen € Höchstvermögen kannst du eine neue Holding gründen. Die Belohnung ist die abgerundete Quadratwurzel aus Höchstvermögen ÷ 100 Millionen €. Du bekommst sie erst bei der Neugründung; die Vorschau erhöht deine aktiven Boni noch nicht.</p><p class="mt8">Jeder Punkt gibt dauerhaft +8 % Produktion, +4 % Forschung und 500 € zusätzliches Startkapital. Das neue Unternehmen beginnt mit seinen Grundressourcen. Betriebe, Geld, Forschung, Finanzanlagen und aktuelle Freischaltungen starten neu. Alle Vermächtnispunkte und sämtliche Holdingprogramme einschließlich laufender Programme bleiben.</p></section><section class="panel mt16"><h3>Erreichte & ausstehende Punktestufen</h3><div class="balance-line"><span>Bereits verfügbare Belohnung</span><strong>+${number(progress.pending)} Punkte</strong></div>${targets.map(points=>`<div class="balance-line"><span>+${number(points)} Punkte bei Neugründung</span><strong class="number">${cash(100000000*points**2)}</strong></div>`).join('')}</section>`;
}

const companyOptions=(s,value='holding')=>[['holding',s.name],...C.controlledCompanies(s).map(c=>[c.id,c.name])].map(([id,name])=>`<option value="${esc(id)}"${id===value?' selected':''}>${esc(name)}</option>`).join('');
export function companySwitch(s,ui){
  if(!C.controlledCompanies(s).length)return '';
  const business=C.scopeCompany(s,ui.companyId),label=ui.companyId==='holding'?'Holding / Stammgeschäft':C.company(s,ui.companyId)?.name;
  return `<div class="company-switch"><label for="company-scope">Aktives Unternehmen</label><select id="company-scope" data-setting="companyId">${companyOptions(s,ui.companyId)}</select><span class="number">${cash(business.cash)} verfügbar</span><small>${esc(label)} · Käufe, Produktion und Kredite betreffen diese Kasse.</small></div>`;
}
function companyFacts(s,c){
  const b=C.companyBalance(s,c),own=C.ownership(s,c),counts=Object.entries(c.state.buildings).filter(([,v])=>v.count).map(([id,v])=>`${v.count}× ${BUILDINGS[id].name}`),properties=Object.entries(c.state.properties).filter(([,v])=>v.count).map(([id,v])=>`${v.count}× ${PROPERTIES[id].name}`);
  if(c.world&&!c.listed&&!c.inspected&&!C.controlled(s,c))return `<div class="detail-grid mt16"><p>Indikativer Unternehmenswert<strong>${cash(C.companyValue(s,c))}</strong></p><p>Stimmrechtsanteil<strong>${pct(own,1)}</strong></p></div><p class="mt16">${esc(C.FOCUSES[c.focus])} · ${c.owner==='legacy'?'Gründer sucht einen strategischen Käufer.':'Eigentümer sucht Liquidität.'}</p><p class="fine-print">Eine Unternehmensprüfung für 150 € erschließt konkrete Anlagen, Kassenbestand und Verbindlichkeiten.</p>`;
  return `<div class="detail-grid mt16"><p>Unternehmenswert<strong>${cash(C.companyValue(s,c))}</strong></p><p>Dein Stimmrechtsanteil<strong>${pct(own,1)}</strong></p><p>Firmenkasse<strong>${cash(c.state.cash)}</strong></p><p>Schulden inkl. Konzernkrediten<strong>${cash(b.debt)}</strong></p><p>Ergebnis letzter Spieltag<strong class="${c.lastDailyProfit<0?'negative':''}">${signed(c.lastDailyProfit)}</strong></p><p>Freie Aktien<strong>${number(C.freeFloat(s,c))} / ${number(c.shares)}</strong></p></div><p class="company-assets">${esc([...counts,...properties].join(' · ')||'Kapital und Finanzanlagen')}</p><p class="fine-print">${c.lastDailyProfit>0?'Ertragskraft trägt die Bewertung.':c.state.debt>c.state.cash?'Finanzierung bindet Liquidität.':'Substanz und Liquidität tragen die Bewertung.'} ${c.state.cash<c.reserve?'Liquiditätsreserve unterschritten.':''}</p>`;
}
export function companiesView(s,ui){
  const a=assets(s),p=s.group.parent,mode=ui.companyTab||'owned';
  const intro=`${head('Eigentum verändert alles','Deine Unternehmensgruppe.','Kapital verteilen. Verantwortung delegieren. Unternehmen übernehmen.')}<div class="summary-grid"><section class="panel"><small>Konzern-Eigenkapital</small><strong class="number primary-value">${cash(a.groupEquity)}</strong></section><section class="panel"><small>Holdingkasse</small><strong class="number primary-value">${cash(s.cash)}</strong></section><section class="panel"><small>Dein Anteil an der Holding</small><strong class="number primary-value">${pct(p.held/p.shares,1)}</strong></section></div><div class="toolbar wrap"><div class="segmented">${[['owned','Eigene Firmen'],['market','Unternehmensmarkt'],['contracts','Verträge & Kredite']].map(([id,name])=>`<button ${act('companyTab',id)} class="${mode===id?'active':''}">${name}</button>`).join('')}</div><button class="primary small" ${act('newCompany')}${disabled(s.tier<1)}>Firma gründen</button></div>`;
  if(mode==='contracts')return intro+corporateContracts(s,ui);
  const list=mode==='owned'?s.group.companies.filter(c=>C.sharesHeld(s,c)>0):s.group.companies.filter(c=>c.world);
  const parent=mode==='owned'?`<section class="panel"><div class="between wrap"><div><h3>${esc(s.name)}</h3><p>${C.FORMS[p.form].name} · ${p.listed?'börsennotierte Holding':'Holding mit Stammgeschäft'}</p></div><button class="small" ${act('parentSettings')}>Holding verwalten</button></div><div class="detail-grid mt16"><p>Wert je eigener Aktie<strong>${money(a.groupEquity/p.shares,2)}</strong></p><p>Ausschüttungsquote<strong>${pct(p.payout,0)}</strong></p><p>Privat ausgeschüttet<strong>${cash(s.group.wallet)}</strong></p><p>Tochteranteile, Buchwert<strong>${cash(a.subsidiaries)}</strong></p></div><p class="fine-print">Konzernvermögen zählt Beteiligungen einmal. Interne Kredite und Kapitalüberträge schaffen keinen zusätzlichen Wert.</p></section>`:'';
  return intro+parent+(!list.length?empty('Dein Stammgeschäft wächst.','Ab 2.000 € Vermögen kannst du eigene Gesellschaften gründen. Weise ihnen Kapital und Assets zu oder erwirb Anteile an bestehenden Firmen.','building'):'')+`<div class="grid2 mt16">${list.map(c=>`<article class="panel company-card" data-key="company:${c.id}"><div class="between wrap"><div><h3>${esc(c.name)}</h3><p>${C.FORMS[c.form].name} · ${c.listed?'Börsennotiert':'Privat'} · ${esc(C.FOCUSES[c.focus])}</p></div><span class="company-badge">${C.controlled(s,c)?'Kontrolliert':C.sharesHeld(s,c)>0?'Beteiligung':'Investitionsziel'}</span></div>${companyFacts(s,c)}<div class="row wrap gap8 mt16">${C.controlled(s,c)?`<button class="primary small" ${act('operateCompany',c.id)}>Betrieb führen</button><button class="small" ${act('companySettings',c.id)}>Führung & Kapital</button>`:''}${c.world&&!c.listed?`<button class="small" ${act('privateOffer',c.id)}>Anteile verhandeln</button>`:''}${!c.world&&c.listed?`<button class="small" ${act('ownShareTrade',c.id)}>Anteile handeln</button>`:''}${c.world&&c.listed?`<button class="small" ${act('companyTrade',c.id)}>Aktien handeln</button>`:''}${c.world&&!c.inspected?`<button class="small" ${act('inspectCompany',c.id)}>Prüfung · 150 €</button>`:''}${c.inspected?'<span class="muted">Unternehmensprüfung liegt vor</span>':''}</div>${c.offer?`<div class="notice mt16"><p>${c.offer.accepted?'Angenommenes Angebot':'Gegenangebot'}: ${cash(c.offer.accepted?c.offer.price:c.offer.counter)} für ${pct(c.offer.quantity/c.shares,1)} · gültig ${duration(c.offer.expires-s.elapsed)}.</p>${c.offer.accepted?`<button class="small" ${act('acceptOffer',c.id)}>Kauf abschließen</button>`:''}</div>`:''}${c.ceo?`<p class="mt16"><strong>${C.CEOS[c.ceo].name}</strong> · ${C.MANDATES[c.mandate]} · ${cash(c.budget)} Investitionsbudget / Tag</p>`:'<p class="mt16 muted">Führung durch dich.</p>'}${c.report.length?`<details class="company-report"><summary>Entscheidungen & Ausschüttungen</summary>${c.report.map(text=>`<p>${esc(text)}</p>`).join('')}</details>`:''}</article>`).join('')}</div>`;
}
function corporateContracts(s,ui){
  return `<div class="row wrap gap8"><button ${act('newAgreement')}>Liefer- oder Mietvertrag</button><button ${act('newCorporateLoan')}>Firmenkredit vergeben</button><button ${act('transferAsset')}>Assets zuordnen</button></div><p class="analysis-note">Verträge verbinden kontrollierte Firmen. Finanzierungen sind auch für fremde Firmen möglich; Rückzahlung hängt von deren Kasse und Sicherheiten ab.</p><div class="grid2">${s.group.agreements.map(a=>`<section class="panel"><h3>${a.kind==='lease'?'Miete':'Lieferung'} · ${esc(a.kind==='lease'?PROPERTIES[a.resource].name:RESOURCES[a.resource].name)}</h3><p>${esc(a.from==='holding'?s.name:C.company(s,a.from)?.name)} an ${esc(a.to==='holding'?s.name:C.company(s,a.to)?.name)}</p><p>${number(a.quantity)} Einheiten · ${cash(a.quantity*a.price)} / Spieltag</p><p>${a.fulfilled} erfüllt · ${a.missed} ausgefallen · noch ${duration(a.end-s.elapsed)}</p><button class="small mt16" ${act('cancelAgreement',a.id)}>Beenden</button></section>`).join('')}${s.group.loans.map(l=>`<section class="panel"><h3>${l.kind==='bond'?'Anleihe':'Kredit'} · ${esc(C.company(s,l.borrower)?.name)}</h3><p>Gläubiger: ${esc(l.lender==='holding'?s.name:C.company(s,l.lender)?.name)}</p><div class="detail-grid mt16"><p>Restforderung<strong>${cash(l.principal)}</strong></p><p>Zins / Spieltag<strong>${pct(l.rate,2)}</strong></p><p>Nächste Rate<strong>${duration(l.next-s.elapsed)}</strong></p><p>Zahlungsstörungen<strong>${l.missed} / 5</strong></p></div>${C.controlled(s,C.company(s,l.borrower))?`<button class="small mt16" ${act('repayCorporateLoan',l.id)}>Vorzeitig vollständig tilgen</button>`:''}<p class="fine-print">${l.kind==='bond'?'Kapital fällig in '+duration(l.end-s.elapsed):'1/20 des ursprünglichen Kapitals je Tag, soweit freie Liquidität besteht.'} Nach fünf nicht bedienten Zinsraten wird die Forderung unter Verwertung von Sicherheiten abgewickelt.</p></section>`).join('')}</div>${s.group.payables.length?`<div class="subheading">Verkäuferfinanzierung</div>${s.group.payables.map(p=>`<div class="panel">${cash(p.amount)} fällig in ${duration(p.due-s.elapsed)}</div>`).join('')}`:''}`;
}
export function newCompanyForm(){return `<label for="firm-name">Unternehmensname</label><input id="firm-name" maxlength="48" value="Neue Gesellschaft"><label class="mt16" for="firm-focus">Startvorlage</label><select id="firm-focus">${Object.entries(C.FOCUSES).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select><label class="mt16" for="firm-capital">Startkapital (€)</label><input id="firm-capital" type="number" min="100" value="1000"><p>Zusätzlich 500 € Gründungskosten. Die Tochter gehört dir vollständig. Vermögenswerte kannst du anschließend zuordnen.</p>`;}
export function companySettingsForm(s,id){
  const c=C.company(s,id);return `<label for="firm-name">Name</label><input id="firm-name" value="${esc(c.name)}" maxlength="48"><div class="auto-form mt16"><div><label for="firm-ceo">Geschäftsführung</label><select id="firm-ceo"><option value="">Du selbst</option>${Object.entries(C.CEOS).map(([key,d])=>`<option value="${key}"${c.ceo===key?' selected':''}>${d.name} · ${cash(d.salary)} / Tag</option>`).join('')}</select></div><div><label for="firm-mandate">Mandat</label><select id="firm-mandate">${Object.entries(C.MANDATES).map(([key,name])=>`<option value="${key}"${c.mandate===key?' selected':''}>${name}</option>`).join('')}</select></div><div><label for="firm-reserve">Mindestliquidität (€)</label><input id="firm-reserve" type="number" min="100" value="${c.reserve}"></div><div><label for="firm-budget">Investitionsbudget / Tag (€)</label><input id="firm-budget" type="number" min="0" value="${c.budget}"></div><div><label for="firm-payout">Gewinnausschüttung (%)</label><input id="firm-payout" type="number" min="0" max="100" value="${c.payout*100}"></div></div><p class="fine-print">Unternehmerin: rentable Betriebe ausbauen. Sanierer: Schulden abbauen und mehr Liquidität halten. Finanzexpertin: Rücklagen verwalten. Entscheidungen jede Spielstunde, Budget und Ausschüttung je Spieltag.</p><div class="divider"></div><div class="row wrap gap8"><button class="small" ${act('companyCapital',id)}>Kapital übertragen</button><button class="small" ${act('companyForm',id)}>Rechtsform</button>${c.form==='ag'&&!c.listed?`<button class="small" ${act('listCompany',id)}>Börsengang</button>`:''}${c.listed?`<button class="small" ${act('raiseCapital',id)}>Neue Aktien ausgeben</button>`:''}${c.world&&C.ownership(s,c)<1?`<button class="small" ${act('buyRemaining',id)}>Restanteile erwerben</button>`:''}${!c.world&&C.companyBalance(s,c).total<0?`<button class="small" ${act('liquidateCompany',c.id)}>Überschuldete Firma abwickeln</button>`:''}${!c.world&&C.ownership(s,c)===1?`<button class="small" ${act('mergeCompany',id)}>Mit Holding verschmelzen</button>`:''}</div>`;
}
export function parentSettingsForm(s){const p=s.group.parent;return `<p>${esc(s.name)} · ${C.FORMS[p.form].name} · ${pct(p.held/p.shares,1)} in deinem Eigentum</p><label class="mt16" for="parent-payout">Gewinnausschüttung (%)</label><input id="parent-payout" type="number" min="0" max="100" value="${p.payout*100}"><p class="fine-print">Die Holding schüttet positive Überschüsse einschließlich erhaltener Tochterdividenden aus, höchstens 10 % der verfügbaren Kasse je Spieltag. Dein Anteil fließt nach 15 % Kapitalertragsteuer in dein Privatvermögen. Die übrigen Eigentümer erhalten ihre Quote.</p><div class="row wrap gap8 mt16"><button class="small" ${act('companyForm','holding')}>Rechtsform ändern</button>${s.group.wallet>0?`<button class="small" ${act('reinvestWallet')}>Privatkapital reinvestieren</button>`:''}${p.form==='ag'&&!p.listed?`<button class="small" ${act('listCompany','holding')}>Holding an die Börse bringen</button>`:''}${p.listed?`<button class="small" ${act('raiseCapital','holding')}>Neue Holdingaktien ausgeben</button>`:''}</div>`;}
export function transferAssetForm(s){return `<div class="auto-form"><div><label for="asset-from">Von</label><select id="asset-from">${companyOptions(s)}</select></div><div><label for="asset-to">An</label><select id="asset-to">${companyOptions(s,C.controlledCompanies(s)[0]?.id)}</select></div></div><label class="mt16" for="asset-kind">Vermögenswert</label><select id="asset-kind">${Object.entries(BUILDINGS).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>`<option value="building:${id}">${d.name}</option>`).join('')}${Object.entries(PROPERTIES).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>`<option value="property:${id}">${d.name}</option>`).join('')}${Object.entries(RESOURCES).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>`<option value="inventory:${id}">Vorrat: ${d.name}</option>`).join('')}</select><label class="mt16" for="asset-count">Anzahl</label><input id="asset-count" type="number" min="1" value="1"><p class="fine-print">Buchwerte und Bestände bleiben erhalten. Freie Assetüberträge sind bei vollständig eigenen Firmen möglich. Infrastruktur baust du am Zielunternehmen.</p>`;}
export function agreementForm(s){return `<div class="auto-form"><div><label for="agreement-from">Lieferant / Vermieter</label><select id="agreement-from">${companyOptions(s)}</select></div><div><label for="agreement-to">Kunde / Mieter</label><select id="agreement-to">${companyOptions(s,C.controlledCompanies(s)[0]?.id)}</select></div></div><label class="mt16" for="agreement-asset">Vertragsgegenstand</label><select id="agreement-asset">${Object.entries(RESOURCES).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>`<option value="supply:${id}">${d.name} · Markt ${money(price(s,id),2)}</option>`).join('')}${Object.entries(PROPERTIES).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>`<option value="lease:${id}">Miete: ${d.name} · Richtpreis ${money(d.rent*.9,2)}</option>`).join('')}</select><div class="auto-form mt16"><div><label for="agreement-quantity">Menge je Spieltag</label><input id="agreement-quantity" type="number" min="1" value="10"></div><div><label for="agreement-price">Preis pro Einheit (€)</label><input id="agreement-price" type="number" min="0.01" step="0.01" value="${price(s,'wood').toFixed(2)}"></div><div><label for="agreement-days">Laufzeit (Spieltage)</label><input id="agreement-days" type="number" min="1" max="60" value="10"></div></div><p class="fine-print">Preise müssen innerhalb von 20 % des Marktpreises liegen. Fehlendes Geld, fehlende Ware oder Lagerplatz lassen eine Lieferung ausfallen. Wohnhäuser stellen dem Mieter 10 Arbeitskräfte je Einheit bereit, Gewerbeparks 500 Lagerplätze und 10 Transport, Logistikimmobilien 2.000 Lagerplätze und 40 Transport. Pachtland erhöht den Getreideertrag um 10 % je Einheit. Außenmiete entfällt für intern vermietete Einheiten.</p>`;}
